 function urlRetornoCadastro(status) {
 const u = new URL(window.location.href);

 ['cadastro_mp', 'payment_id', 'status', 'collection_id', 'collection_status',
 'preference_id', 'external_reference', 'payment_type', 'merchant_order_id',
 'site_id', 'processing_mode', 'merchant_account_id'].forEach(function(k) {
 u.searchParams.delete(k);
 });
 u.searchParams.set('cadastro_mp', status);
 return u.toString();
 }

 function isMercadoPagoSandbox(mp) {
 mp = mp || ((TAXA_CADASTRO && TAXA_CADASTRO.mercadoPago) ? TAXA_CADASTRO.mercadoPago : {}) || {};

 if (mp.sandbox === true) return true;
 if (mp.sandbox === false) return false;
 const token = String(mp.accessToken || '').trim();
 if (!token) return true;

 if (/^TEST-/i.test(token)) return true;
 if (/sandbox/i.test(token)) return true;

 if (/^APP_USR-/i.test(token)) return false;
 return false;
 }

 function escolherInitPointMercadoPago(pref, mp) {
 pref = pref || {};
 const sandbox = isMercadoPagoSandbox(mp);
 if (sandbox) {
 return pref.sandbox_init_point || pref.init_point || '';
 }
 return pref.init_point || pref.sandbox_init_point || '';
 }

 async function criarPreferenciaMercadoPago(dados) {
 const mp = (TAXA_CADASTRO && TAXA_CADASTRO.mercadoPago) ? TAXA_CADASTRO.mercadoPago : {};
 const valor = Number(TAXA_CADASTRO.valor) || 0;
 const body = {
 items: [{
 id: 'taxa-cadastro-aldineicar',
 title: TAXA_CADASTRO.descricao || 'Ativacao ALDINEICAR',
 description: 'Taxa de ativacao da conta ' + (dados.email || ''),
 quantity: 1,
 currency_id: 'BRL',
 unit_price: valor
 }],
 payer: {
 name: dados.nome || '',
 email: dados.email || ''
 },
 external_reference: dados.txid || ('CAD-' + Date.now()),
 statement_descriptor: 'ALDINEICAR',
 back_urls: {
 success: urlRetornoCadastro('success'),
 failure: urlRetornoCadastro('failure'),
 pending: urlRetornoCadastro('pending')
 },
 auto_return: 'approved',
 metadata: {
 tipo: 'taxa_cadastro',
 email: dados.email || '',
 nome: dados.nome || ''
 }
 };

 if (mp.preferenceProxyUrl) {
 const res = await fetch(mp.preferenceProxyUrl, {
 method: 'POST',
 headers: { 'Content-Type': 'application/json' },
 body: JSON.stringify(body)
 });
 const json = await res.json().catch(function() { return {}; });
 if (!res.ok) throw new Error(json.message || json.error || ('HTTP ' + res.status));
 return json;
 }

 if (!mp.accessToken) {
 throw new Error('Access Token do Mercado Pago não configurado em TAXA_CADASTRO.mercadoPago.accessToken');
 }

 const res = await fetch('https://api.mercadopago.com/checkout/preferences', {
 method: 'POST',
 headers: {
 'Content-Type': 'application/json',
 'Authorization': 'Bearer ' + mp.accessToken
 },
 body: JSON.stringify(body)
 });
 const json = await res.json().catch(function() { return {}; });
 if (!res.ok) {
 const msg = (json && json.message) || (json && json.error) || ('Erro MP HTTP ' + res.status);
 throw new Error(msg);
 }
 return json;
 }

 async function verificarPagamentoMercadoPago(paymentId) {
 const mp = (TAXA_CADASTRO && TAXA_CADASTRO.mercadoPago) ? TAXA_CADASTRO.mercadoPago : {};
 if (!paymentId) return null;
 if (!mp.accessToken) return { id: paymentId, status: 'unknown' };
 try {
 const res = await fetch('https://api.mercadopago.com/v1/payments/' + encodeURIComponent(paymentId), {
 headers: { 'Authorization': 'Bearer ' + mp.accessToken }
 });
 if (!res.ok) return null;
 return await res.json();
 } catch (e) {
 console.warn('verify mp', e);
 return null;
 }
 }

 async function buscarPagamentoMercadoPagoPorReferencia(externalRef) {
 const mp = (TAXA_CADASTRO && TAXA_CADASTRO.mercadoPago) ? TAXA_CADASTRO.mercadoPago : {};
 if (!externalRef || !mp.accessToken) return null;
 try {
 const url = 'https://api.mercadopago.com/v1/payments/search?sort=date_created&criteria=desc&external_reference=' + encodeURIComponent(externalRef);
 const res = await fetch(url, { headers: { 'Authorization': 'Bearer ' + mp.accessToken } });
 if (!res.ok) return null;
 const json = await res.json();
 const results = (json && json.results) ? json.results : [];
 if (!results.length) return null;

 var approved = results.find(function(p) { return p && p.status === 'approved'; });
 return approved || results[0];
 } catch (e) {
 console.warn('search mp', e);
 return null;
 }
 }

 let __mpPollTimer = null;
 function pararPollMercadoPago() {
 if (__mpPollTimer) {
 clearInterval(__mpPollTimer);
 __mpPollTimer = null;
 }
 }

 function iniciarPollAprovacaoMercadoPago(opts) {
 opts = opts || {};
 pararPollMercadoPago();
 var tentativas = 0;
 var maxTentativas = opts.maxTentativas || 40;
 var intervalMs = opts.intervalMs || 3000;
 var stTxt = document.getElementById('signupMpStatusTxt');
 var btnConf = document.getElementById('btnSignupConfirmarPagamento');

 async function tick() {
 tentativas++;
 var pend = carregarSignupPendente();
 if (!pend) {
 pararPollMercadoPago();
 return;
 }
 if (stTxt) {
 stTxt.innerHTML = 'Aguardando confirmação do PIX no Mercado Pago...<br><span style="color:#94a3b8;font-size:12px;font-weight:500;">Isso pode levar alguns segundos após o pagamento. (' + tentativas + '/' + maxTentativas + ')</span>';
 }
 var pag = null;
 if (pend.mpPaymentId) {
 pag = await verificarPagamentoMercadoPago(pend.mpPaymentId);
 }
 if (!pag || pag.status !== 'approved') {
 pag = await buscarPagamentoMercadoPagoPorReferencia(pend.txid || pend.mpPreferenceId || '');
 }
 if (pag && pag.status === 'approved') {
 pararPollMercadoPago();
 pend.mpPaymentId = String(pag.id || pend.mpPaymentId || '');
 salvarSignupPendente(pend);
 if (stTxt) stTxt.innerHTML = 'PIX <b style="color:#22c55e;">aprovado</b>! Liberando sua conta...';
 if (typeof mostrarToast === 'function') mostrarToast('PIX aprovado! Liberando conta...', 'sucesso');
 await confirmarPagamentoECriarConta({ mpAprovado: true, forcar: true });
 return;
 }
 if (tentativas >= maxTentativas) {
 pararPollMercadoPago();
 if (stTxt) stTxt.innerHTML = 'Ainda não vimos a confirmação automática.<br>Se o PIX já caiu, toque no botão abaixo.';
 if (btnConf) {
 btnConf.style.display = 'block';
 btnConf.textContent = '✓ Já paguei — liberar minha conta';
 btnConf.onclick = function() { confirmarPagamentoECriarConta({ mpAprovado: true, forcar: true }); };
 }
 }
 }

 tick();
 __mpPollTimer = setInterval(tick, intervalMs);
 }

 async function iniciarCadastroPixManual(nome, email, password) {
 if (!TAXA_CADASTRO.pixChave) {
 if (typeof mostrarToast === 'function') mostrarToast('Chave PIX de cadastro não configurada.', 'erro');
 return;
 }
 const txid = ('CAD' + Date.now()).substring(0, 25);
 let payload = '';
 try {
 if (typeof gerarPayloadPixSimples === 'function') {
 payload = gerarPayloadPixSimples({
 chave: String(TAXA_CADASTRO.pixChave).replace(/\s/g, ''),
 nome: TAXA_CADASTRO.pixNome || 'ALDINEICAR',
 cidade: TAXA_CADASTRO.pixCidade || 'SATIRO DIAS',
 valor: Number(TAXA_CADASTRO.valor) || 0,
 txid: txid
 });
 }
 } catch (e) { console.error(e); }
 if (!payload) {
 if (typeof mostrarToast === 'function') mostrarToast('Não foi possível gerar o PIX.', 'erro');
 return;
 }
 salvarSignupPendente({ nome, email, password, txid, payload, valor: Number(TAXA_CADASTRO.valor) || 0, metodo: 'pix_manual' });
 atualizarUITaxaCadastro();
 const ta = document.getElementById('signupPixCopia');
 if (ta) ta.value = payload;
 const chaveInfo = document.getElementById('signupPixChave');
 if (chaveInfo) chaveInfo.textContent = 'Chave: ' + TAXA_CADASTRO.pixChave;
 const instr = document.getElementById('signupPixInstrucao');
 if (instr) instr.textContent = 'Pague o PIX abaixo e depois confirme para criar sua conta.';
 const boxManual = document.getElementById('signupPixManualBox');
 if (boxManual) boxManual.style.display = 'block';
 const st = document.getElementById('signupMpStatusBox');
 if (st) st.style.display = 'none';
 const btnConf = document.getElementById('btnSignupConfirmarPagamento');
 if (btnConf) btnConf.style.display = 'block';
 desenharQrSignup(payload);
 mostrarSignupPix();
 }

 async function iniciarCadastroMercadoPago(nome, email, password) {
 const btn = document.getElementById('btnSignupContinuar');
 const textoOriginal = btn ? btn.innerText : '';
 if (btn) { btn.innerText = 'Abrindo Mercado Pago...'; btn.disabled = true; }
 const txid = ('CAD' + Date.now()).substring(0, 25);
 try {
 salvarSignupPendente({
 nome, email, password, txid,
 valor: Number(TAXA_CADASTRO.valor) || 0,
 metodo: 'mercadopago'
 });
 const pref = await criarPreferenciaMercadoPago({ nome, email, txid });
 const mpCfg = (TAXA_CADASTRO && TAXA_CADASTRO.mercadoPago) ? TAXA_CADASTRO.mercadoPago : {};
 const initPoint = escolherInitPointMercadoPago(pref, mpCfg);
 if (!initPoint) throw new Error('Preferência criada, mas sem link de pagamento (init_point).');

 try {
 console.log('[MP] ambiente:', isMercadoPagoSandbox(mpCfg) ? 'TESTE (sandbox)' : 'PRODUÇÃO',
 '| preference:', pref.id, '| url:', initPoint.substring(0, 48) + '...');
 } catch (e) {}

 const pend = carregarSignupPendente() || {};
 pend.mpPreferenceId = pref.id || '';
 salvarSignupPendente(pend);

 if (typeof mostrarToast === 'function') mostrarToast('Redirecionando ao Mercado Pago...', 'aviso');
 window.location.href = initPoint;
 } catch (e) {
 console.error(e);
 if (typeof mostrarToast === 'function') {
 mostrarToast('Mercado Pago: ' + (e.message || 'erro') + ' — tentando PIX manual.', 'erro');
 }
 await iniciarCadastroPixManual(nome, email, password);
 } finally {
 if (btn) { btn.innerText = textoOriginal || 'Pagar com Mercado Pago'; btn.disabled = false; }
 }
 }

 async function iniciarCadastroComPagamento() {
 const nome = (document.getElementById('signupName').value || '').trim();
 const email = (document.getElementById('signupEmail').value || '').trim();
 const password = document.getElementById('signupPassword').value || '';

 if (!nome) {
 if (typeof mostrarToast === 'function') mostrarToast('Informe seu nome completo.', 'aviso');
 return;
 }
 if (!email || !password || password.length < 6) {
 if (typeof mostrarToast === 'function') mostrarToast('Preencha e-mail e senha (mín. 6 caracteres).', 'aviso');
 return;
 }

 if (!TAXA_CADASTRO || TAXA_CADASTRO.ativo === false || TAXA_CADASTRO.metodo === 'off') {
 salvarSignupPendente({ nome, email, password, txid: 'FREE', valor: 0, metodo: 'off' });
 await confirmarPagamentoECriarConta({ forcar: true });
 return;
 }

 if (TAXA_CADASTRO.metodo === 'mercadopago') {
 var mp = TAXA_CADASTRO.mercadoPago || {};
 var mpOk = (mp.accessToken && String(mp.accessToken).trim()) || (mp.preferenceProxyUrl && String(mp.preferenceProxyUrl).trim());
 if (mpOk) {
 await iniciarCadastroMercadoPago(nome, email, password);
 return;
 }

 if (typeof mostrarToast === 'function') {
 mostrarToast('Mercado Pago ainda sem Access Token — usando PIX manual.', 'aviso');
 }
 await iniciarCadastroPixManual(nome, email, password);
 return;
 }
 await iniciarCadastroPixManual(nome, email, password);
 }

 async function confirmarPagamentoECriarConta(opts) {
 opts = opts || {};
 const pend = carregarSignupPendente();
 if (!pend) {
 if (typeof mostrarToast === 'function') mostrarToast('Preencha os dados primeiro.', 'aviso');
 voltarSignupDados();
 return;
 }

 if (pend.metodo === 'mercadopago' && !opts.forcar && !opts.mpAprovado) {
 if (typeof mostrarToast === 'function') {
 mostrarToast('Conclua o pagamento no Mercado Pago. Se já pagou, aguarde o retorno automático.', 'aviso');
 }
 return;
 }

 const { nome, email, password, txid, valor } = pend;
 const btn = document.getElementById('btnSignupConfirmarPagamento') || document.getElementById('btnSignupContinuar');
 const textoOriginal = btn ? btn.innerText : '';
 if (btn) { btn.innerText = 'Criando conta...'; btn.disabled = true; }

 try {
 const { data, error } = await supabaseClient.auth.signUp({
 email,
 password,
 options: {
 data: {
 nome: nome,
 taxa_cadastro_paga: true,
 taxa_valor: valor || (TAXA_CADASTRO && TAXA_CADASTRO.valor) || 0,
 taxa_txid: txid || '',
 taxa_metodo: pend.metodo || 'pix_manual',
 taxa_mp_payment_id: pend.mpPaymentId || '',
 taxa_mp_preference_id: pend.mpPreferenceId || '',
 taxa_paga_em: new Date().toISOString()
 }
 }
 });

 if (error) {
 var msg = (error && error.message) ? String(error.message) : 'erro';
 if (/already|registered|exists|já/i.test(msg)) {
 if (typeof mostrarToast === 'function') mostrarToast('Conta já existe. Tentando entrar...', 'aviso');
 try {
 var loginRes = await supabaseClient.auth.signInWithPassword({ email: email, password: password });
 if (!loginRes.error && loginRes.data && loginRes.data.user) {
 limparSignupPendente();
 var lo = document.getElementById('loginOverlay'); if (lo) lo.style.display = 'none';
 if (typeof carregarDadosDoUsuario === 'function') await carregarDadosDoUsuario(loginRes.data.user.id);
 if (typeof mostrarToast === 'function') mostrarToast('Login liberado!', 'sucesso');
 return;
 }
 } catch (eLogin) { console.warn(eLogin); }
 toggleTab('login');
 var le = document.getElementById('loginEmail'); if (le) le.value = email;
 if (typeof mostrarToast === 'function') mostrarToast('Conta existe. Entre com a senha usada no cadastro.', 'aviso');
 return;
 }
 if (typeof mostrarToast === 'function') mostrarToast('Erro ao cadastrar: ' + msg, 'erro');
 return;
 }

 try {
 const log = JSON.parse(localStorage.getItem('aldineicar_cadastros_pix') || '[]');
 log.unshift({
 email: email, nome: nome, txid: txid, valor: valor || 0,
 metodo: pend.metodo || '',
 mpPaymentId: pend.mpPaymentId || '',
 em: new Date().toISOString()
 });
 localStorage.setItem('aldineicar_cadastros_pix', JSON.stringify(log.slice(0, 50)));
 } catch (e) {}

 var entrou = false;
 try {
 var loginRes2 = await supabaseClient.auth.signInWithPassword({ email: email, password: password });
 if (!loginRes2.error && loginRes2.data && loginRes2.data.user) {
 entrou = true;
 limparSignupPendente();
 var lo2 = document.getElementById('loginOverlay'); if (lo2) lo2.style.display = 'none';
 if (typeof carregarDadosDoUsuario === 'function') await carregarDadosDoUsuario(loginRes2.data.user.id);
 if (typeof mostrarToast === 'function') mostrarToast('Pagamento ok! Conta liberada.', 'sucesso');
 }
 } catch (e3) { console.warn(e3); }

 if (!entrou) {
 limparSignupPendente();
 if (typeof mostrarToast === 'function') {
 mostrarToast('Conta criada! Se não entrar, desative confirmação de e-mail no Supabase (Auth → Providers → Email).', 'sucesso');
 }
 ['signupName','signupEmail','signupPassword'].forEach(function(id) {
 const el = document.getElementById(id); if (el) el.value = '';
 });
 voltarSignupDados();
 toggleTab('login');
 const loginEmail = document.getElementById('loginEmail');
 if (loginEmail) loginEmail.value = email;
 const loginPass = document.getElementById('loginPassword');
 if (loginPass) loginPass.value = password;
 }

 try {
 const u = new URL(window.location.href);
 if (u.searchParams.has('cadastro_mp') || u.searchParams.has('payment_id') || u.searchParams.has('collection_id')) {
 u.search = '';
 window.history.replaceState({}, '', u.pathname + u.hash);
 }
 } catch (e) {}
 } catch (err) {
 console.error(err);
 if (typeof mostrarToast === 'function') mostrarToast('Erro no processo de cadastro.', 'erro');
 } finally {
 if (btn) { btn.innerText = textoOriginal || '✓ Já paguei — criar minha conta'; btn.disabled = false; }
 }
 }

 async function processarRetornoMercadoPago() {
 try {
 const params = new URLSearchParams(window.location.search);
 var flag = params.get('cadastro_mp');
 var paymentId = params.get('payment_id') || params.get('collection_id') || params.get('paymentId') || '';
 var statusRaw = (params.get('status') || params.get('collection_status') || params.get('payment_status') || flag || '').toLowerCase();
 if (!flag && (paymentId || statusRaw === 'approved' || params.get('preference_id') || params.get('collection_id'))) {
 if (statusRaw === 'approved' || statusRaw === 'success') flag = 'success';
 else if (statusRaw === 'pending' || statusRaw === 'in_process') flag = 'pending';
 else if (statusRaw === 'rejected' || statusRaw === 'failure' || statusRaw === 'cancelled' || statusRaw === 'canceled') flag = 'failure';
 else if (paymentId) flag = 'success';
 }
 if (!flag) {
 var pend0 = carregarSignupPendente();
 if (pend0 && pend0.metodo === 'mercadopago' && pend0.email) {
 try { toggleTab('signup'); } catch (e) {}
 mostrarSignupPix();
 var stBox0 = document.getElementById('signupMpStatusBox');
 var stTxt0 = document.getElementById('signupMpStatusTxt');
 var boxManual0 = document.getElementById('signupPixManualBox');
 if (boxManual0) boxManual0.style.display = 'none';
 if (stBox0) stBox0.style.display = 'block';
 if (stTxt0) stTxt0.innerHTML = 'Cadastro pendente para <b>' + pend0.email + '</b>. Se o pagamento já caiu, toque abaixo.';
 var btnConf0 = document.getElementById('btnSignupConfirmarPagamento');
 if (btnConf0) {
 btnConf0.style.display = 'block';
 btnConf0.textContent = '✓ Já paguei — liberar minha conta';
 btnConf0.onclick = function() { confirmarPagamentoECriarConta({ mpAprovado: true, forcar: true }); };
 }
 iniciarPollAprovacaoMercadoPago({ maxTentativas: 40, intervalMs: 3000 });
 }
 return;
 }

 try { toggleTab('signup'); } catch (e) {}
 mostrarSignupPix();
 const boxManual = document.getElementById('signupPixManualBox');
 if (boxManual) boxManual.style.display = 'none';
 const stBox = document.getElementById('signupMpStatusBox');
 const stTxt = document.getElementById('signupMpStatusTxt');
 if (stBox) stBox.style.display = 'block';
 const btnConf = document.getElementById('btnSignupConfirmarPagamento');
 if (btnConf) btnConf.style.display = 'none';

 const status = statusRaw || String(flag).toLowerCase();
 const pend = carregarSignupPendente();

 if (!pend) {
 if (stTxt) stTxt.innerHTML = 'Pagamento ok, mas os dados do cadastro não estão neste navegador.<br>Preencha o <b>mesmo e-mail e senha</b> e toque em Continuar / Já paguei (não precisa pagar de novo).';
 if (typeof mostrarToast === 'function') mostrarToast('Preencha novamente e-mail e senha para liberar.', 'aviso');
 voltarSignupDados();
 var btnCont = document.getElementById('btnSignupContinuar');
 if (btnCont) {
 btnCont.textContent = '✓ Já paguei — criar conta';
 btnCont.onclick = async function() {
 var nome = (document.getElementById('signupName').value || '').trim();
 var email = (document.getElementById('signupEmail').value || '').trim();
 var password = document.getElementById('signupPassword').value || '';
 if (!nome || !email || password.length < 6) {
 if (typeof mostrarToast === 'function') mostrarToast('Preencha nome, e-mail e senha.', 'aviso');
 return;
 }
 salvarSignupPendente({
 nome: nome, email: email, password: password,
 txid: 'MP-RECOVER-' + Date.now(),
 valor: (TAXA_CADASTRO && TAXA_CADASTRO.valor) || 0,
 metodo: 'mercadopago',
 mpPaymentId: paymentId || ''
 });
 await confirmarPagamentoECriarConta({ mpAprovado: true, forcar: true });
 };
 }
 return;
 }

 if (flag === 'failure' || status === 'rejected' || status === 'failure') {
 if (stTxt) stTxt.innerHTML = 'Pagamento <b style="color:#f87171;">não aprovado</b>. Você pode tentar novamente.';
 if (btnConf) {
 btnConf.style.display = 'block';
 btnConf.textContent = 'Tentar pagar de novo';
 btnConf.onclick = function() { iniciarCadastroMercadoPago(pend.nome, pend.email, pend.password); };
 }
 if (typeof mostrarToast === 'function') mostrarToast('Pagamento não aprovado.', 'erro');
 return;
 }

 if (flag === 'pending' || status === 'pending' || status === 'in_process') {
 if (paymentId) {
 pend.mpPaymentId = String(paymentId);
 salvarSignupPendente(pend);
 }
 if (stTxt) stTxt.innerHTML = 'PIX em processamento. Estamos confirmando automaticamente com o Mercado Pago...';
 if (btnConf) {
 btnConf.style.display = 'block';
 btnConf.textContent = '✓ Já paguei — liberar agora';
 btnConf.onclick = function() {
 confirmarPagamentoECriarConta({ mpAprovado: true, forcar: true });
 };
 }

 iniciarPollAprovacaoMercadoPago({ maxTentativas: 40, intervalMs: 3000 });
 return;
 }

 if (stTxt) stTxt.textContent = 'Pagamento detectado! Liberando sua conta...';
 let aprovado = (status === 'approved' || flag === 'success' || flag === 'approved');
 if (paymentId) {
 const pag = await verificarPagamentoMercadoPago(paymentId);
 if (pag) {
 if (pag.status === 'approved') aprovado = true;
 else if (pag.status === 'rejected' || pag.status === 'cancelled') aprovado = false;
 pend.mpPaymentId = String(pag.id || paymentId);
 salvarSignupPendente(pend);
 } else {
 pend.mpPaymentId = String(paymentId);
 salvarSignupPendente(pend);
 if (flag === 'success') aprovado = true;
 }
 } else if (flag === 'success') {
 aprovado = true;
 }

 if (aprovado) {
 await confirmarPagamentoECriarConta({ mpAprovado: true, forcar: true });
 } else {
 if (stTxt) stTxt.innerHTML = 'Não confirmamos automaticamente. Se o valor já caiu, toque abaixo.';
 if (btnConf) {
 btnConf.style.display = 'block';
 btnConf.textContent = '✓ Já paguei — liberar minha conta';
 btnConf.onclick = function() { confirmarPagamentoECriarConta({ mpAprovado: true, forcar: true }); };
 }
 }
 } catch (e) {
 console.error('retorno MP', e);
 }
 }

