function renderizarVendas(vendas) {
 const lista = document.getElementById('lista-vendas');
 lista.innerHTML = '';

 vendas.forEach(venda => {
 lista.innerHTML += `
 <tr>
 <td>${venda.data}</td>
 <td>${venda.item}</td>
 <td>R$ ${venda.valor}</td>
 <td>${venda.status}</td>
 </tr>
 `;
 });
}

let graficoFinanceiroInstance = null;

function parseDataHistorico(dataStr) {
 if (!dataStr) return null;
 try {
 if (String(dataStr).includes('/')) {
 const parte = String(dataStr).split(',')[0].trim();
 const bits = parte.split('/');
 if (bits.length >= 3) {
 const dia = parseInt(bits[0], 10);
 const mes = parseInt(bits[1], 10);
 const ano = parseInt(bits[2], 10);
 if (dia && mes && ano) return new Date(ano, mes - 1, dia);
 }
 }
 const d = new Date(dataStr);
 if (!isNaN(d.getTime())) return d;
 } catch (e) {}
 return null;
}

function isRegistroVenda(item) {
 if (!item) return false;
 if (item.tipo_registro === 'VENDA_DIRETA_BALCAO' || item.tipo_registro === 'LOJA_VIRTUAL') return true;
 if (item.tipo_servico === '[VENDA DIRETA]') return true;
 if (item.veiculo && item.veiculo.tipo_servico && String(item.veiculo.tipo_servico).includes('[VENDA DIRETA]')) return true;
 return false;
}

function isRegistroAgendamento(item) {
 if (!item) return false;
 return item.tipo_registro === 'AGENDAMENTO' || !!(item.agendamento && item.agendamento.data);
}

function isVendaPaga(item) {
 if (!item) return false;
 const status = String(item.status || '').trim().toLowerCase();

 return status.includes('pago') && !status.includes('aguardando');
}

function isAgendamentoConcluido(item) {
 if (!isRegistroAgendamento(item)) return false;
 return String(item.status || '').trim().toLowerCase() === 'concluído' ||
 String(item.status || '').trim().toLowerCase() === 'concluido';
}

function valorVenda(item) {
 let v = item.total_pago || item.valor_total || item.totalCobrado || 0;
 if (typeof v === 'string') v = parseFloat(v.replace('R$', '').replace(/\./g, '').replace(',', '.').trim()) || 0;
 return parseFloat(v) || 0;
}

function valorOrcamento(item) {
 return parseFloat(item.totalCobrado) || parseFloat(item.total) || 0;
}

function valorServicoAgenda(item) {
 if (!item) return 0;
 let v = item.totalCobrado;
 if (v === undefined || v === null || v === '' || parseFloat(v) === 0) {
 v = item.servico_preco;
 }
 if (v === undefined || v === null || v === '') v = 0;
 if (typeof v === 'string') v = parseFloat(v.replace('R$', '').replace(/\./g, '').replace(',', '.').trim()) || 0;
 return parseFloat(v) || 0;
}

function dataReferenciaDashboard(item) {

 if (item.concluido_em) {
 const d = new Date(item.concluido_em);
 if (!isNaN(d.getTime())) return d;
 }
 if (item.confirmado_em) {
 const d = new Date(item.confirmado_em);
 if (!isNaN(d.getTime())) return d;
 }
 if (item.agendamento && item.agendamento.data) {
 const d = new Date(item.agendamento.data + 'T12:00:00');
 if (!isNaN(d.getTime())) return d;
 }
 return parseDataHistorico(item.data);
}

function custoMateriaisOrc(item) {
 let c = item.totalMateriaisCalculado !== undefined ? item.totalMateriaisCalculado : (item.totalMateriais || 0);
 return parseFloat(c) || 0;
}

function obterPeriodoDashboard() {
 const inputIni = document.getElementById('dashDataInicio');
 const inputFim = document.getElementById('dashDataFim');
 let ini = inputIni && inputIni.value ? new Date(inputIni.value + 'T00:00:00') : null;
 let fim = inputFim && inputFim.value ? new Date(inputFim.value + 'T23:59:59') : null;

 if (!ini && !fim) {
 const ano = new Date().getFullYear();
 ini = new Date(ano, 0, 1);
 fim = new Date(ano, 11, 31, 23, 59, 59);
 if (inputIni) inputIni.value = `${ano}-01-01`;
 if (inputFim) inputFim.value = `${ano}-12-31`;
 } else if (ini && !fim) {
 fim = new Date();
 fim.setHours(23, 59, 59, 999);
 if (inputFim) inputFim.value = fim.toISOString().slice(0, 10);
 } else if (!ini && fim) {
 ini = new Date(fim.getFullYear(), 0, 1);
 if (inputIni) inputIni.value = ini.toISOString().slice(0, 10);
 }

 if (ini && fim && ini > fim) {
 const tmp = ini; ini = fim; fim = tmp;
 if (inputIni) inputIni.value = ini.toISOString().slice(0, 10);
 if (inputFim) inputFim.value = fim.toISOString().slice(0, 10);
 }
 return { ini, fim };
}

function definirPeriodoRapido(tipo) {
 const inputIni = document.getElementById('dashDataInicio');
 const inputFim = document.getElementById('dashDataFim');
 if (!inputIni || !inputFim) return;

 const hoje = new Date();
 let ini, fim;

 if (tipo === 'mes') {
 ini = new Date(hoje.getFullYear(), hoje.getMonth(), 1);
 fim = new Date(hoje.getFullYear(), hoje.getMonth() + 1, 0);
 } else if (tipo === 'ano') {
 ini = new Date(hoje.getFullYear(), 0, 1);
 fim = new Date(hoje.getFullYear(), 11, 31);
 } else {

 let minT = null, maxT = null;
 (historico || []).forEach(item => {
 const d = parseDataHistorico(item.data);
 if (!d) return;
 const t = d.getTime();
 if (minT === null || t < minT) minT = t;
 if (maxT === null || t > maxT) maxT = t;
 });
 (gastosOficina || []).forEach(g => {
 const d = typeof parseDataGasto === 'function' ? parseDataGasto(g) : null;
 if (!d) return;
 const t = d.getTime();
 if (minT === null || t < minT) minT = t;
 if (maxT === null || t > maxT) maxT = t;
 });
 ini = minT !== null ? new Date(minT) : new Date(hoje.getFullYear(), 0, 1);
 fim = maxT !== null ? new Date(maxT) : hoje;
 }

 const fmt = (d) => {
 const y = d.getFullYear();
 const m = String(d.getMonth() + 1).padStart(2, '0');
 const day = String(d.getDate()).padStart(2, '0');
 return `${y}-${m}-${day}`;
 };
 inputIni.value = fmt(ini);
 inputFim.value = fmt(fim);
 renderDashboard();
}

function dataNoPeriodo(data, ini, fim) {
 if (!data) return false;
 const t = data.getTime();
 if (ini && t < ini.getTime()) return false;
 if (fim && t > fim.getTime()) return false;
 return true;
}

function parseDataGasto(g) {
 if (!g) return null;
 const raw = g.data || g.data_gasto || g.created_at || '';
 if (!raw) return null;
 if (typeof parseDataHistorico === 'function') {
 const d = parseDataHistorico(raw);
 if (d && !isNaN(d.getTime())) return d;
 }
 const m = String(raw).match(/^(\d{4})-(\d{2})-(\d{2})/);
 if (m) {
 const d = new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]), 12, 0, 0);
 if (!isNaN(d.getTime())) return d;
 }
 const d2 = new Date(raw);
 return isNaN(d2.getTime()) ? null : d2;
}

function calcularDadosPorPeriodo(ini, fim) {
 const mapa = {};
 let totalFatOrc = 0, totalMat = 0, totalVendas = 0, totalServicos = 0, totalGastos = 0;
 let qtdOrc = 0, qtdVendas = 0, qtdServicos = 0, qtdGastos = 0;
 const nomes = ['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];

 function garantirMes(chave, dataRef) {
 if (!mapa[chave]) {
 mapa[chave] = { fatOrc: 0, materiais: 0, vendas: 0, servicos: 0, gastos: 0, qtdOrc: 0, qtdVendas: 0, qtdServicos: 0, qtdGastos: 0, label: '' };
 }
 if (dataRef) mapa[chave].label = nomes[dataRef.getMonth()] + '/' + dataRef.getFullYear();
 return mapa[chave];
 }

 const lista = Array.isArray(historico) ? historico : [];
 lista.forEach(item => {
 const data = dataReferenciaDashboard(item);
 if (!dataNoPeriodo(data, ini, fim)) return;

 const chave = data.getFullYear() + '-' + String(data.getMonth() + 1).padStart(2, '0');
 const slot = garantirMes(chave, data);

 if (isRegistroVenda(item)) {
 if (!isVendaPaga(item)) return;
 const v = valorVenda(item);
 slot.vendas += v;
 slot.qtdVendas += 1;
 totalVendas += v;
 qtdVendas += 1;
 return;
 }

 if (isRegistroAgendamento(item)) {
 if (!isAgendamentoConcluido(item)) return;
 const v = valorServicoAgenda(item);
 if (v <= 0) return;
 slot.servicos += v;
 slot.qtdServicos += 1;
 totalServicos += v;
 qtdServicos += 1;
 return;
 }

 const status = (item.status || '').toString().trim().toLowerCase();
 if (status !== 'pago') return;
 const fat = valorOrcamento(item);
 const mat = custoMateriaisOrc(item);
 slot.fatOrc += fat;
 slot.materiais += mat;
 slot.qtdOrc += 1;
 totalFatOrc += fat;
 totalMat += mat;
 qtdOrc += 1;
 });

 (Array.isArray(gastosOficina) ? gastosOficina : []).forEach(g => {
 const data = parseDataGasto(g);
 if (!dataNoPeriodo(data, ini, fim)) return;
 const chave = data.getFullYear() + '-' + String(data.getMonth() + 1).padStart(2, '0');
 const slot = garantirMes(chave, data);
 const v = parseFloat(g.valor) || 0;
 if (v <= 0) return;
 slot.gastos += v;
 slot.qtdGastos += 1;
 totalGastos += v;
 qtdGastos += 1;
 });

 const chaves = Object.keys(mapa).sort();
 return {
 totalFatOrc, totalMat, totalVendas, totalServicos, totalGastos,
 qtdOrc, qtdVendas, qtdServicos, qtdGastos,
 labels: chaves.map(k => mapa[k].label),
 fatOrc: chaves.map(k => mapa[k].fatOrc),
 servicos: chaves.map(k => mapa[k].servicos),
 materiais: chaves.map(k => mapa[k].materiais),
 vendas: chaves.map(k => mapa[k].vendas),
 gastos: chaves.map(k => mapa[k].gastos),
 linhas: chaves.map(k => ({
 label: mapa[k].label,
 fatOrc: mapa[k].fatOrc,
 servicos: mapa[k].servicos,
 materiais: mapa[k].materiais,
 vendas: mapa[k].vendas,
 gastos: mapa[k].gastos,
 qtdOrc: mapa[k].qtdOrc,
 qtdServicos: mapa[k].qtdServicos,
 qtdVendas: mapa[k].qtdVendas,
 qtdGastos: mapa[k].qtdGastos
 }))
 };
}

function formatarBRL(valor) {
 const n = Number(valor) || 0;
 return n.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
}

function formatarDataBR(d) {
 if (!d) return '--';
 return d.toLocaleDateString('pt-BR');
}

function renderDashboard() {
 const canvas = document.getElementById('graficoFinanceiro');
 if (!canvas) return;

 if (typeof Chart === 'undefined') {
 if (canvas.__chartLoading) return;
 canvas.__chartLoading = true;
 const placeholder = canvas.parentElement;
 if (placeholder && !placeholder.querySelector('.chart-loading-hint')) {
 const hint = document.createElement('p');
 hint.className = 'chart-loading-hint';
 hint.style.cssText = 'text-align:center;color:#94a3b8;font-size:13px;font-weight:600;padding:24px;';
 hint.textContent = 'Carregando gráfico...';
 placeholder.appendChild(hint);
 }
 ensureChartJS().then(function() {
 canvas.__chartLoading = false;
 const h = placeholder && placeholder.querySelector('.chart-loading-hint');
 if (h) h.remove();
 renderDashboard();
 }).catch(function(err) {
 canvas.__chartLoading = false;
 console.error(err);
 if (typeof mostrarToast === 'function') mostrarToast('Não foi possível carregar o gráfico.', 'erro');
 });
 return;
 }

 const { ini, fim } = obterPeriodoDashboard();
 const dados = calcularDadosPorPeriodo(ini, fim);

 const labelEl = document.getElementById('dashPeriodoLabel');
 if (labelEl) {
 labelEl.innerText = 'Período: ' + formatarDataBR(ini) + ' → ' + formatarDataBR(fim);
 }

 const set = (id, val) => { const el = document.getElementById(id); if (el) el.innerText = val; };
 const totalGastos = dados.totalGastos || 0;
 const lucroTotal = (dados.totalFatOrc + dados.totalServicos + dados.totalVendas) - dados.totalMat - totalGastos;
 set('kpi-fat-orc', formatarBRL(dados.totalFatOrc));
 set('kpi-servicos', formatarBRL(dados.totalServicos));
 set('kpi-materiais', formatarBRL(dados.totalMat));
 set('kpi-vendas', formatarBRL(dados.totalVendas));
 set('kpi-gastos', formatarBRL(totalGastos));
 set('kpi-lucro', formatarBRL(lucroTotal));
 set('kpi-fat-orc-sub', dados.qtdOrc + ' orçamento(s) pago(s) no período');
 set('kpi-servicos-sub', dados.qtdServicos + ' serviço(s) concluído(s)');
 set('kpi-materiais-sub', 'Materiais das OS pagas no período');
 set('kpi-vendas-sub', dados.qtdVendas + ' venda(s) paga(s) no período');
 set('kpi-gastos-sub', (dados.qtdGastos || 0) + ' despesa(s) no período');
 set('kpi-lucro-sub', 'Receitas − materiais − gastos oficina');

 const tbody = document.getElementById('tabela-resumo-mensal');
 if (tbody) {
 let html = '';
 dados.linhas.forEach(m => {
 const g = m.gastos || 0;
 const lucro = (m.fatOrc + (m.servicos || 0) + m.vendas) - m.materiais - g;
 html += `<tr>
 <td>${m.label}</td>
 <td class="val-pos">${formatarBRL(m.fatOrc)}</td>
 <td style="color:#7c3aed;font-weight:700;">${formatarBRL(m.servicos || 0)}</td>
 <td class="val-neg">${formatarBRL(m.materiais)}</td>
 <td style="color:#64748b;font-weight:700;">${formatarBRL(g)}</td>
 <td class="${lucro >= 0 ? 'val-pos' : 'val-neg'}">${formatarBRL(lucro)}</td>
 <td style="color:#d97706;font-weight:700;">${formatarBRL(m.vendas)}</td>
 <td>${m.qtdOrc}</td>
 <td>${m.qtdServicos || 0}</td>
 <td>${m.qtdVendas}</td>
 </tr>`;
 });
 tbody.innerHTML = html || `<tr><td colspan="10" style="text-align:center;color:#94a3b8;padding:20px;">Nenhum dado neste período</td></tr>`;
 }

 if (graficoFinanceiroInstance) graficoFinanceiroInstance.destroy();

 const labels = dados.labels.length ? dados.labels : ['Sem dados'];
 const fatOrc = dados.labels.length ? dados.fatOrc : [0];
 const servicos = dados.labels.length ? (dados.servicos || []) : [0];
 const mat = dados.labels.length ? dados.materiais : [0];
 const vendas = dados.labels.length ? dados.vendas : [0];
 const gastosChart = dados.labels.length ? (dados.gastos || []) : [0];

 graficoFinanceiroInstance = new Chart(canvas, {
 type: 'bar',
 data: {
 labels,
 datasets: [
 {
 label: 'Orçamentos (Pagos)',
 data: fatOrc,
 backgroundColor: 'rgba(16, 185, 129, 0.85)',
 borderRadius: 6,
 borderSkipped: false,
 maxBarThickness: 22
 },
 {
 label: 'Serviços concluídos',
 data: servicos,
 backgroundColor: 'rgba(139, 92, 246, 0.85)',
 borderRadius: 6,
 borderSkipped: false,
 maxBarThickness: 22
 },
 {
 label: 'Materiais',
 data: mat,
 backgroundColor: 'rgba(225, 29, 72, 0.8)',
 borderRadius: 6,
 borderSkipped: false,
 maxBarThickness: 22
 },
 {
 label: 'Vendas Loja',
 data: vendas,
 backgroundColor: 'rgba(245, 158, 11, 0.85)',
 borderRadius: 6,
 borderSkipped: false,
 maxBarThickness: 22
 },
 {
 label: 'Gastos Oficina',
 data: gastosChart,
 backgroundColor: 'rgba(100, 116, 139, 0.9)',
 borderRadius: 6,
 borderSkipped: false,
 maxBarThickness: 22
 }
 ]
 },
 options: {
 responsive: true,
 maintainAspectRatio: false,
 interaction: { mode: 'index', intersect: false },
 plugins: {
 legend: { display: false },
 tooltip: {
 callbacks: {
 label: (ctx) => ctx.dataset.label + ': ' + formatarBRL(ctx.parsed.y)
 }
 }
 },
 scales: {
 x: { grid: { display: false }, ticks: { font: { weight: '600', size: 11 }, color: '#64748b' } },
 y: {
 beginAtZero: true,
 grid: { color: '#f1f5f9' },
 ticks: {
 font: { size: 11 },
 color: '#94a3b8',
 callback: (v) => v >= 1000 ? 'R$ ' + (v / 1000).toFixed(1) + 'k' : 'R$ ' + v
 }
 }
 }
 }
 });
}

const HORARIOS_PADRAO_AGENDA = ['08:00','09:00','10:00','11:00','13:00','14:00','15:00','16:00','17:00'];
const NOMES_DIA_AGENDA = ['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];

function obterDisponibilidadePadrao() {
 return {
 diasSemana: { '0': false, '1': true, '2': true, '3': true, '4': true, '5': true, '6': false },
 horarios: HORARIOS_PADRAO_AGENDA.slice(),
 bloqueados: []
 };
}

function obterDisponibilidadeOficina(fonte) {
 const base = obterDisponibilidadePadrao();
 const src = fonte || (typeof dadosOficina !== 'undefined' ? dadosOficina : null);
 if (!src || !src.disponibilidade) return base;
 const d = src.disponibilidade;
 return {
 diasSemana: Object.assign({}, base.diasSemana, d.diasSemana || {}),
 horarios: Array.isArray(d.horarios) && d.horarios.length ? d.horarios.slice() : base.horarios,
 bloqueados: Array.isArray(d.bloqueados) ? d.bloqueados.slice() : []
 };
}

function dataISO(d) {
 const y = d.getFullYear();
 const m = String(d.getMonth() + 1).padStart(2, '0');
 const day = String(d.getDate()).padStart(2, '0');
 return y + '-' + m + '-' + day;
}

function formatarDataBR_ISO(iso) {
 if (!iso) return '';
 const p = iso.split('-');
 if (p.length !== 3) return iso;
 return p[2] + '/' + p[1] + '/' + p[0];
}

function diaEstaDisponivel(isoDate, disp) {
 if (!isoDate || !disp) return false;
 if ((disp.bloqueados || []).includes(isoDate)) return false;
 const dt = new Date(isoDate + 'T12:00:00');
 if (isNaN(dt.getTime())) return false;
 const wd = String(dt.getDay());
 return !!(disp.diasSemana && disp.diasSemana[wd]);
}

function listarProximasDatasDisponiveis(disp, diasFrente) {
 const out = [];
 const hoje = new Date();
 hoje.setHours(0, 0, 0, 0);
 const limite = diasFrente || 60;
 for (let i = 0; i <= limite && out.length < 40; i++) {
 const d = new Date(hoje);
 d.setDate(hoje.getDate() + i);
 const iso = dataISO(d);
 if (diaEstaDisponivel(iso, disp)) out.push(iso);
 }
 return out;
}

function renderPainelDisponibilidade() {
 const boxDias = document.getElementById('disp-dias-semana');
 const boxHoras = document.getElementById('disp-horarios');
 const boxBloq = document.getElementById('disp-lista-bloqueados');
 if (!boxDias || !boxHoras) return;

 const disp = obterDisponibilidadeOficina();
 if (!dadosOficina.disponibilidade) dadosOficina.disponibilidade = disp;

 boxDias.innerHTML = '';
 for (let i = 0; i < 7; i++) {
 const on = !!(disp.diasSemana && disp.diasSemana[String(i)]);
 const btn = document.createElement('button');
 btn.type = 'button';
 btn.textContent = NOMES_DIA_AGENDA[i];
 btn.style.cssText = 'padding:10px 14px;border-radius:10px;border:1px solid ' + (on ? '#10b981' : '#e2e8f0') +
 ';background:' + (on ? '#d1fae5' : '#f8fafc') + ';color:' + (on ? '#065f46' : '#64748b') +
 ';font-weight:700;font-size:13px;cursor:pointer;';
 btn.onclick = (function(dia) {
 return function() {
 const d = obterDisponibilidadeOficina();
 d.diasSemana[String(dia)] = !d.diasSemana[String(dia)];
 dadosOficina.disponibilidade = d;
 renderPainelDisponibilidade();
 };
 })(i);
 boxDias.appendChild(btn);
 }

 boxHoras.innerHTML = '';
 HORARIOS_PADRAO_AGENDA.forEach(function(h) {
 const on = (disp.horarios || []).indexOf(h) >= 0;
 const btn = document.createElement('button');
 btn.type = 'button';
 btn.textContent = h;
 btn.style.cssText = 'padding:8px 12px;border-radius:8px;border:1px solid ' + (on ? '#3b82f6' : '#e2e8f0') +
 ';background:' + (on ? '#dbeafe' : '#f8fafc') + ';color:' + (on ? '#1d4ed8' : '#64748b') +
 ';font-weight:700;font-size:12px;cursor:pointer;';
 btn.onclick = (function(hora) {
 return function() {
 const d = obterDisponibilidadeOficina();
 const idx = d.horarios.indexOf(hora);
 if (idx >= 0) d.horarios.splice(idx, 1);
 else d.horarios.push(hora);
 d.horarios.sort();
 dadosOficina.disponibilidade = d;
 renderPainelDisponibilidade();
 };
 })(h);
 boxHoras.appendChild(btn);
 });

 if (boxBloq) {
 const lista = (disp.bloqueados || []).slice().sort();
 if (lista.length === 0) {
 boxBloq.innerHTML = '<span style="font-size:12px;color:#94a3b8;">Nenhuma data bloqueada.</span>';
 } else {
 boxBloq.innerHTML = lista.map(function(iso) {
 return '<span style="display:inline-flex;align-items:center;gap:6px;background:#fef2f2;color:#b91c1c;border:1px solid #fecaca;padding:6px 10px;border-radius:20px;font-size:12px;font-weight:700;">'
 + formatarDataBR_ISO(iso)
 + ' <button type="button" onclick="desbloquearDataDisponibilidade(\'' + iso + '\')" style="border:none;background:transparent;color:#b91c1c;cursor:pointer;font-weight:800;">✕</button></span>';
 }).join('');
 }
 }
}

function bloquearDataDisponibilidade() {
 const input = document.getElementById('disp-data-bloquear');
 if (!input || !input.value) {
 alert('Escolha uma data para bloquear.');
 return;
 }
 const d = obterDisponibilidadeOficina();
 if (d.bloqueados.indexOf(input.value) < 0) d.bloqueados.push(input.value);
 d.bloqueados.sort();
 dadosOficina.disponibilidade = d;
 input.value = '';
 renderPainelDisponibilidade();
}

function desbloquearDataDisponibilidade(iso) {
 const d = obterDisponibilidadeOficina();
 d.bloqueados = (d.bloqueados || []).filter(function(x) { return x !== iso; });
 dadosOficina.disponibilidade = d;
 renderPainelDisponibilidade();
}

async function salvarDisponibilidadeAgenda() {
 if (!dadosOficina.disponibilidade) {
 dadosOficina.disponibilidade = obterDisponibilidadePadrao();
 }
 try {
 if (typeof salvarNoBanco === 'function') await salvarNoBanco();
 if (typeof mostrarToast === 'function') mostrarToast('Disponibilidade salva!', 'sucesso');
 else alert('Disponibilidade salva!');
 } catch (e) {
 alert('Erro ao salvar: ' + (e.message || e));
 }
}

let __dispClienteCache = null;

async function carregarDatasDisponiveisCliente() {
 const selData = document.getElementById('cliOrcData');
 const selHora = document.getElementById('cliOrcHora');
 if (!selData) return;

 selData.innerHTML = '<option value="">Carregando datas...</option>';
 if (selHora) selHora.innerHTML = '<option value="">Escolha a data primeiro</option>';

 let disp = (typeof obterDisponibilidadePadrao === 'function')
 ? obterDisponibilidadePadrao()
 : { diasSemana: { '0': false, '1': true, '2': true, '3': true, '4': true, '5': true, '6': false }, horarios: ['08:00','09:00','10:00','11:00','13:00','14:00','15:00','16:00','17:00'], bloqueados: [] };

 try {
 const params = new URLSearchParams(window.location.search);
 const id = (typeof idOficinaDaLojaAtual !== 'undefined' && idOficinaDaLojaAtual)
 ? idOficinaDaLojaAtual
 : (params.get('id') || params.get('loja') || params.get('user_id'));

 if (id && typeof supabaseClient !== 'undefined') {
 try {
 const { data, error } = await supabaseClient
 .from('user_data')
 .select('dados_oficina, historico')
 .eq('user_id', id)
 .maybeSingle();
 if (error) {
 console.warn('Disponibilidade: falha ao buscar oficina', error);
 } else if (data) {
 if (data.dados_oficina && typeof obterDisponibilidadeOficina === 'function') {
 disp = obterDisponibilidadeOficina(data.dados_oficina);
 }
 window.__histAgendaCliente = Array.isArray(data.historico) ? data.historico : [];
 }
 } catch (netErr) {
 console.warn('Disponibilidade: rede/offline, usando padrão', netErr);
 }
 }
 } catch (e) {
 console.warn('Disponibilidade: erro geral, usando padrão', e);
 }

 __dispClienteCache = disp;

 try {
 const datas = (typeof listarProximasDatasDisponiveis === 'function')
 ? listarProximasDatasDisponiveis(disp, 60)
 : [];
 if (!datas.length) {
 selData.innerHTML = '<option value="">Sem datas disponíveis no momento</option>';
 return;
 }
 const nomes = (typeof NOMES_DIA_AGENDA !== 'undefined') ? NOMES_DIA_AGENDA : ['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];
 selData.innerHTML = '<option value="">Selecione a data</option>' + datas.map(function(iso) {
 const dt = new Date(iso + 'T12:00:00');
 const nomeDia = nomes[dt.getDay()] || '';
 const label = (typeof formatarDataBR_ISO === 'function') ? formatarDataBR_ISO(iso) : iso;
 return '<option value="' + iso + '">' + nomeDia + ' · ' + label + '</option>';
 }).join('');
 } catch (e) {
 console.error(e);
 selData.innerHTML = '<option value="">Erro ao montar datas</option>';
 }
}

function atualizarHorariosCliente() {
 const selData = document.getElementById('cliOrcData');
 const selHora = document.getElementById('cliOrcHora');
 if (!selData || !selHora) return;

 const iso = selData.value;
 if (!iso) {
 selHora.innerHTML = '<option value="">Escolha a data primeiro</option>';
 return;
 }

 const disp = __dispClienteCache || obterDisponibilidadePadrao();
 if (!diaEstaDisponivel(iso, disp)) {
 selHora.innerHTML = '<option value="">Dia indisponível</option>';
 return;
 }

 const ocupados = {};
 (window.__histAgendaCliente || []).forEach(function(item) {
 if (!item || item.tipo_registro !== 'AGENDAMENTO') return;
 if ((item.status || '') === 'Cancelado') return;
 const ag = item.agendamento || {};
 if (ag.data === iso && ag.hora) ocupados[ag.hora] = true;
 });

 const livres = (disp.horarios || HORARIOS_PADRAO_AGENDA).filter(function(h) {
 return !ocupados[h];
 });

 if (livres.length === 0) {
 selHora.innerHTML = '<option value="">Sem horários livres neste dia</option>';
 return;
 }
 selHora.innerHTML = '<option value="">Selecione o horário</option>' + livres.map(function(h) {
 return '<option value="' + h + '">' + h + '</option>';
 }).join('');
}

let filtroAgendaAtual = 'todos';
let filtroPeriodoAgenda = 'todos';
let calMesRef = null;
let calDiaSelecionado = null;

const NOMES_MES_AGENDA = ['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];
const NOMES_DIA_COMPLETO = ['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'];

function calGarantirMes() {
 if (!calMesRef || isNaN(calMesRef.getTime())) {
 const h = new Date();
 calMesRef = new Date(h.getFullYear(), h.getMonth(), 1);
 }
}

function calMudarMes(delta) {
 calGarantirMes();
 calMesRef = new Date(calMesRef.getFullYear(), calMesRef.getMonth() + delta, 1);
 calDiaSelecionado = null;
 renderAgenda();
}

function calIrHoje() {
 const h = new Date();
 calMesRef = new Date(h.getFullYear(), h.getMonth(), 1);
 calDiaSelecionado = _hojeISO();
 renderAgenda();
}

function calSelecionarDia(iso) {
 calDiaSelecionado = iso;

 if (iso && iso.length >= 7) {
 const y = parseInt(iso.slice(0, 4), 10);
 const m = parseInt(iso.slice(5, 7), 10) - 1;
 calGarantirMes();
 if (calMesRef.getFullYear() !== y || calMesRef.getMonth() !== m) {
 calMesRef = new Date(y, m, 1);
 }
 }
 renderAgenda();
}

function filtrarAgenda(status) {

 filtrarAgendaUnificado(status === 'todos' ? 'todos' : status);
}

function filtrarAgendaPeriodo(periodo) {
 filtrarAgendaUnificado(periodo);
}

function filtrarAgendaUnificado(chave) {

 const periodos = ['hoje', 'semana', 'atrasados'];
 if (chave === 'todos') {
 filtroAgendaAtual = 'todos';
 filtroPeriodoAgenda = 'todos';
 } else if (periodos.includes(chave)) {
 filtroPeriodoAgenda = chave;
 filtroAgendaAtual = 'todos';
 if (chave === 'hoje') calIrHoje();
 } else {
 filtroAgendaAtual = chave;
 filtroPeriodoAgenda = 'todos';
 }
 document.querySelectorAll('.agenda-chip').forEach(b => b.classList.remove('active'));
 const btn = document.getElementById('f-ag-' + chave);
 if (btn) btn.classList.add('active');
 renderAgenda();
}

function _hojeISO() {
 const h = new Date();
 return h.getFullYear() + '-' + String(h.getMonth()+1).padStart(2,'0') + '-' + String(h.getDate()).padStart(2,'0');
}

function _inicioSemanaISO() {
 const h = new Date();
 const dia = h.getDay();
 const diff = dia === 0 ? -6 : 1 - dia;
 const seg = new Date(h);
 seg.setDate(h.getDate() + diff);
 return dataISO(seg);
}

function _fimSemanaISO() {
 const ini = new Date(_inicioSemanaISO() + 'T12:00:00');
 ini.setDate(ini.getDate() + 6);
 return dataISO(ini);
}

function _agendamentoEstaAtrasado(item) {
 const ag = item.agendamento || {};
 if (!ag.data) return false;
 const st = item.status || '';
 if (st === 'Concluído' || st === 'Cancelado') return false;
 const hoje = _hojeISO();
 if (ag.data < hoje) return true;
 if (ag.data === hoje && ag.hora) {
 const agora = new Date();
 const parts = String(ag.hora).split(':');
 const hh = parseInt(parts[0], 10);
 const mm = parseInt(parts[1] || '0', 10);
 if (!isNaN(hh) && (agora.getHours() > hh || (agora.getHours() === hh && agora.getMinutes() > mm))) return true;
 }
 return false;
}

function _agendamentoEHoje(item) {
 const ag = item.agendamento || {};
 return ag.data === _hojeISO();
}

function coletarAgendamentos() {
 const lista = Array.isArray(historico) ? historico : [];
 const out = [];
 lista.forEach((item, idx) => {
 if (item.tipo_registro === 'AGENDAMENTO' || (item.agendamento && item.agendamento.data)) {
 out.push({ item, idx });
 }
 });
 out.sort((a, b) => {
 const da = ((a.item.agendamento && a.item.agendamento.data) || '') + ((a.item.agendamento && a.item.agendamento.hora) || '');
 const db = ((b.item.agendamento && b.item.agendamento.data) || '') + ((b.item.agendamento && b.item.agendamento.hora) || '');
 return da.localeCompare(db);
 });
 return out;
}

function formatarDataBR_ISO(iso) {
 if (!iso) return '--/--/----';
 const p = String(iso).split('-');
 if (p.length !== 3) return iso;
 return p[2] + '/' + p[1] + '/' + p[0];
}

function renderAgendaContadores(todos) {

 renderCalResumo(todos);
}

function renderCalResumo(todos) {
 calGarantirMes();
 const y = calMesRef.getFullYear();
 const m = calMesRef.getMonth();
 const prefix = y + '-' + String(m + 1).padStart(2, '0');
 let total = 0, pend = 0, conc = 0, canc = 0;
 todos.forEach(({ item }) => {
 const d = (item.agendamento || {}).data || '';
 if (!d.startsWith(prefix)) return;
 total++;
 const st = item.status || 'Agendado';
 if (st === 'Concluído') conc++;
 else if (st === 'Cancelado') canc++;
 else pend++;
 });
 const set = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = String(v); };
 set('cal-kpi-total', total);
 set('cal-kpi-pend', pend);
 set('cal-kpi-conc', conc);
 set('cal-kpi-canc', canc);
}

function agruparAgendamentosPorDia(todos) {
 const map = {};
 todos.forEach(({ item, idx }) => {
 const d = (item.agendamento || {}).data || '';
 if (!d) return;
 if (!map[d]) map[d] = [];
 map[d].push({ item, idx });
 });
 return map;
}

function renderCalGrid(todos) {
 const grid = document.getElementById('cal-grid');
 const label = document.getElementById('cal-mes-label');
 if (!grid) return;
 calGarantirMes();
 const y = calMesRef.getFullYear();
 const m = calMesRef.getMonth();
 if (label) label.textContent = NOMES_MES_AGENDA[m] + ' ' + y;

 const porDia = agruparAgendamentosPorDia(todos);
 const primeiro = new Date(y, m, 1);
 const ultimo = new Date(y, m + 1, 0);
 const startPad = primeiro.getDay();
 const totalDias = ultimo.getDate();
 const hoje = _hojeISO();
 if (!calDiaSelecionado) calDiaSelecionado = hoje;

 let html = '';

 for (let i = 0; i < startPad; i++) {
 html += '<div class="cal-cell cal-cell-empty"></div>';
 }
 for (let dia = 1; dia <= totalDias; dia++) {
 const iso = y + '-' + String(m + 1).padStart(2, '0') + '-' + String(dia).padStart(2, '0');
 const lista = porDia[iso] || [];
 let nPend = 0, nConc = 0, nCanc = 0;
 const nomes = [];
 lista.forEach(({ item }) => {
 const st = item.status || 'Agendado';
 if (st === 'Concluído') nConc++;
 else if (st === 'Cancelado') nCanc++;
 else nPend++;
 const nome = (item.cliente && item.cliente.nome) || '';
 if (nome && nomes.length < 2) nomes.push(nome.split(' ')[0]);
 });
 const classes = ['cal-cell'];
 if (iso === hoje) classes.push('cal-cell-hoje');
 if (iso === calDiaSelecionado) classes.push('cal-cell-sel');
 if (lista.length) classes.push('cal-cell-has');

 let badges = '';
 if (nPend) badges += '<span class="cal-badge cal-badge-pend">' + nPend + ' pend.</span>';
 if (nConc) badges += '<span class="cal-badge cal-badge-conc">' + nConc + ' concluíd.</span>';
 if (nCanc) badges += '<span class="cal-badge cal-badge-canc">' + nCanc + ' cancel.</span>';

 let nomesHtml = '';
 if (lista.length === 1 && nomes[0]) {
 nomesHtml = '<span class="cal-nome-evt">' + nomes[0] + '</span>';
 } else if (lista.length > 1 && nomes.length) {
 nomesHtml = '<span class="cal-nome-evt">' + nomes.join(', ') + (lista.length > 2 ? '…' : '') + '</span>';
 }

 html += '<button type="button" class="' + classes.join(' ') + '" onclick="calSelecionarDia(\'' + iso + '\')">'
 + '<span class="cal-num">' + dia + '</span>'
 + '<div class="cal-cell-body">' + badges + nomesHtml + '</div>'
 + '</button>';
 }

 const totalCells = startPad + totalDias;
 const resto = totalCells % 7;
 if (resto) {
 for (let i = 0; i < 7 - resto; i++) html += '<div class="cal-cell cal-cell-empty"></div>';
 }
 grid.innerHTML = html;
}

function renderListaDiaSelecionado(todos) {
 const container = document.getElementById('lista-agenda');
 const titulo = document.getElementById('cal-dia-titulo');
 if (!container) return;

 const iso = calDiaSelecionado || _hojeISO();
 if (titulo) {
 try {
 const dt = new Date(iso + 'T12:00:00');
 const nomeDia = NOMES_DIA_COMPLETO[dt.getDay()] || '';
 const eHoje = iso === _hojeISO();
 titulo.textContent = (eHoje ? 'Hoje · ' : '') + nomeDia + ', ' + formatarDataBR_ISO(iso);
 } catch (e) {
 titulo.textContent = formatarDataBR_ISO(iso);
 }
 }

 let agendamentos = todos.filter(({ item }) => ((item.agendamento || {}).data || '') === iso);

 if (filtroAgendaAtual !== 'todos') {
 agendamentos = agendamentos.filter(({ item }) => (item.status || '') === filtroAgendaAtual);
 }

 if (agendamentos.length === 0) {
 container.innerHTML = '<div class="cal-empty-card"><div style="font-size:32px;">📅</div><p>Nenhum agendamento neste dia.</p><button type="button" class="btn-page-action" onclick="abrirModalNovoAgendamento()">＋ Novo agendamento</button></div>';
 return;
 }

 let html = '';
 agendamentos.forEach(({ item, idx }) => {
 const cliente = item.cliente || {};
 const veiculo = item.veiculo || {};
 const ag = item.agendamento || {};
 const status = item.status || 'Agendado';
 let badgeClass = 'agenda-badge-pendente';
 if (status === 'Confirmado') badgeClass = 'agenda-badge-ok';
 if (status === 'Cancelado') badgeClass = 'agenda-badge-cancel';
 if (status === 'Concluído') badgeClass = 'agenda-badge-done';

 const eHoje = _agendamentoEHoje(item);
 const eAtrasado = _agendamentoEstaAtrasado(item);
 let cardClass = 'ag-item';
 if (eAtrasado) cardClass += ' atrasado';
 else if (eHoje) cardClass += ' hoje';

 const tel = cliente.tel || '';
 const telLimpo = String(tel).replace(/\D/g, '');
 const nomeOficina = (typeof dadosOficina !== 'undefined' && dadosOficina.nome) ? dadosOficina.nome : 'ALDINEICAR';
 const msgWa = encodeURIComponent('Olá ' + (cliente.nome || '') + '! Sobre seu agendamento em ' + (ag.label || '') + ' — ' + nomeOficina);
 const msgLembrar = encodeURIComponent('Olá ' + (cliente.nome || '') + '! Lembrete: seu horário está marcado para ' + (ag.label || '') + '. — ' + nomeOficina);

 let extraBadge = '';
 if (eAtrasado) extraBadge = '<span class="agenda-badge agenda-badge-atrasado">Atrasado</span>';
 else if (eHoje) extraBadge = '<span class="agenda-badge agenda-badge-hoje">Hoje</span>';

 html += '<div class="' + cardClass + '">'
 + '<div class="ag-item-main">'
 + '<div class="ag-hora">' + (ag.hora || '--:--') + '</div>'
 + '<div class="ag-info">'
 + '<div class="ag-nome">' + (cliente.nome || 'Cliente') + '</div>'
 + '<div class="ag-sub">' + (veiculo.modelo || '—') + (veiculo.tipo_servico ? ' · ' + veiculo.tipo_servico : '') + '</div>'
 + '</div>'
 + '<span class="agenda-badge ' + badgeClass + '">' + status + '</span>' + extraBadge
 + '</div>'
 + ((item.fotos && item.fotos.length) ? '<div class="ag-fotos">' + item.fotos.map(function(f){ return '<img src="'+f+'" alt="Foto" onclick="abrirLightboxFoto(this.src)">'; }).join('') + '</div>' : '')
 + '<details class="ag-mais"><summary>Ações</summary><div class="ag-acoes">';

 if (status === 'Agendado') {
 html += '<button onclick="alterarStatusAgendamento(' + idx + ',\'Confirmado\')" class="agenda-btn agenda-btn-ok">✓ Confirmar</button>'
 + '<button onclick="alterarStatusAgendamento(' + idx + ',\'Cancelado\')" class="agenda-btn agenda-btn-cancel">✕ Cancelar</button>';
 }
 if (status === 'Confirmado') {
 html += '<button onclick="alterarStatusAgendamento(' + idx + ',\'Concluído\')" class="agenda-btn agenda-btn-done">✓ Concluir</button>'
 + '<button onclick="alterarStatusAgendamento(' + idx + ',\'Cancelado\')" class="agenda-btn agenda-btn-cancel">✕ Cancelar</button>';
 }
 if (status !== 'Cancelado' && status !== 'Concluído') {
 html += '<button onclick="converterAgendamentoEmOrcamento(' + idx + ')" class="agenda-btn agenda-btn-convert">📋 Orçamento</button>';
 }
 if (telLimpo) {
 html += '<a href="https://wa.me/55' + telLimpo + '?text=' + msgWa + '" target="_blank" class="agenda-btn agenda-btn-wa">📱 WhatsApp</a>';
 if (status !== 'Cancelado' && status !== 'Concluído') {
 html += '<a href="https://wa.me/55' + telLimpo + '?text=' + msgLembrar + '" target="_blank" class="agenda-btn agenda-btn-lembrar">🔔 Lembrar</a>';
 }
 }
 html += '<button onclick="deletarAgendamento(' + idx + ')" class="agenda-btn agenda-btn-del">🗑️</button>'
 + '</div></details></div>';
 });
 container.innerHTML = html;
}

function renderAgenda() {
 const todos = coletarAgendamentos();
 renderCalResumo(todos);
 renderCalGrid(todos);
 renderListaDiaSelecionado(todos);
}

async function alterarStatusAgendamento(idx, novoStatus) {
 if (idx < 0 || idx >= historico.length) return;
 const item = historico[idx];
 item.status = novoStatus;

 if (String(novoStatus).toLowerCase().indexOf('conclu') === 0) {
 item.concluido_em = new Date().toISOString();
 const precoVitrine = parseFloat(item.servico_preco) || 0;
 const cobrado = parseFloat(item.totalCobrado) || 0;
 if (precoVitrine > 0 && cobrado <= 0) {
 item.totalCobrado = precoVitrine;
 }

 if (!item.lucro && (parseFloat(item.totalCobrado) || 0) > 0) {
 item.lucro = parseFloat(item.totalCobrado) || 0;
 }
 }

 await salvarNoBanco();
 renderAgenda();
 if (typeof renderDashboard === 'function') {
 const dash = document.getElementById('aba-dashboard');
 if (dash && dash.style.display !== 'none') renderDashboard();
 }
 if (typeof mostrarToast === 'function') {
 if (String(novoStatus).toLowerCase().indexOf('conclu') === 0) {
 const v = valorServicoAgenda(item);
 mostrarToast(v > 0
 ? ('Serviço concluído! R$ ' + v.toFixed(2).replace('.', ',') + ' no dashboard.')
 : 'Serviço concluído!', 'sucesso');
 } else {
 mostrarToast('Status: ' + novoStatus, 'sucesso');
 }
 }
}

async function deletarAgendamento(idx) {
 abrirConfirmacao('Excluir este agendamento?', async function() {
 if (idx < 0 || idx >= historico.length) return;
 historico.splice(idx, 1);
 await salvarNoBanco();
 renderAgenda();
 if (typeof mostrarToast === 'function') mostrarToast('Agendamento removido.', 'sucesso');
 });
}

function converterAgendamentoEmOrcamento(idx) {
 if (idx < 0 || idx >= historico.length) return;
 const item = historico[idx];
 const cliente = item.cliente || {};
 const veiculo = item.veiculo || {};
 const setVal = (id, v) => { const el = document.getElementById(id); if (el) el.value = v || ''; };
 setVal('clienteNome', cliente.nome);
 setVal('clienteEndereco', cliente.endereco || '');
 setVal('clienteTel', cliente.tel || '');
 setVal('clienteCidade', cliente.cidade || 'Sátrio Dias/BA');
 setVal('veiculoModelo', veiculo.modelo || '');
 setVal('veiculoPlaca', veiculo.placa || '');
 setVal('veiculoAno', veiculo.ano || '');
 setVal('veiculoCor', veiculo.cor || '');
 setVal('tipoServico', veiculo.tipo_servico || '');
 if (typeof fotosOrcamentoAtual !== 'undefined') {
 fotosOrcamentoAtual = (item.fotos && Array.isArray(item.fotos)) ? item.fotos.slice() : [];
 if (typeof renderFotosOrcamento === 'function') renderFotosOrcamento();
 }
 setVal('valorCliente', '');
 materiais.forEach(m => { m.qtd = 0; });
 maoObraItens = [];
 if (typeof render === 'function') render();
 if (typeof renderMaoObra === 'function') renderMaoObra();
 if (typeof atualizarResumo === 'function') atualizarResumo();
 historico[idx].convertido_orcamento = true;
 salvarNoBanco(true);
 mostrarAba('materiais');
 if (typeof mostrarToast === 'function') mostrarToast('Dados do cliente carregados no resumo. Monte o orçamento!', 'sucesso');
}

