function notificacoesAtivas() {
 const v = localStorage.getItem(NOTIF_KEY);
 return v === null ? true : v === '1';
}
function atualizarBotaoNotifUI() {
 const btn = document.getElementById('btn-toggle-notif');
 if (!btn) return;
 btn.innerText = notificacoesAtivas() ? '🔔 Ativadas' : '🔔 Desativadas';
 btn.style.background = notificacoesAtivas() ? '#10b981' : '#475569';
}
async function alternarNotificacoes() {
 localStorage.setItem(NOTIF_KEY, notificacoesAtivas() ? '0' : '1');
 if (notificacoesAtivas()) await solicitarPermissaoNotificacoes();
 atualizarBotaoNotifUI();
 mostrarToast(notificacoesAtivas() ? 'Notificações ativadas' : 'Notificações desativadas', 'aviso');
}
async function solicitarPermissaoNotificacoes() {
 if (!('Notification' in window)) return false;
 if (Notification.permission === 'granted') return true;
 if (Notification.permission === 'denied') return false;
 try { return (await Notification.requestPermission()) === 'granted'; } catch(e) { return false; }
}
function obterIdsVistos() { try { return JSON.parse(localStorage.getItem(NOTIF_SEEN_KEY)||'[]'); } catch(e){ return []; } }
function salvarIdsVistos(ids) { localStorage.setItem(NOTIF_SEEN_KEY, JSON.stringify(Array.from(new Set(ids)).slice(-200))); }
function coletarIdsNotificaveis(lista) {
 const ids = [];
 (lista||[]).forEach((item, idx) => {
 if (item.tipo_registro === 'AGENDAMENTO') ids.push(item.id_agendamento || ('agd-'+idx));
 if (item.tipo_registro === 'VENDA_DIRETA_BALCAO' || item.tipo_registro === 'LOJA_VIRTUAL') ids.push(item.id_venda || ('vnd-'+idx));
 });
 return ids;
}
function dispararNotificacaoBrowser(titulo, corpo) {
 if (!notificacoesAtivas() || !('Notification' in window) || Notification.permission !== 'granted') return;
 try { const n = new Notification(titulo, { body: corpo }); n.onclick = () => { window.focus(); n.close(); }; } catch(e){}
}
function verificarNovasNotificacoes(lista) {
 if (!notificacoesAtivas() || !usuarioAtualId) return;
 const atuais = coletarIdsNotificaveis(lista);
 const vistos = obterIdsVistos();
 if (vistos.length === 0 && atuais.length > 0) { salvarIdsVistos(atuais); return; }
 const novos = atuais.filter(id => !vistos.includes(id));
 if (novos.length === 0) { salvarIdsVistos([...vistos, ...atuais]); return; }
 let qtdAgd=0, qtdVnd=0;
 (lista||[]).forEach((item, idx) => {
 const idA = item.id_agendamento || ('agd-'+idx);
 const idV = item.id_venda || ('vnd-'+idx);
 if (novos.includes(idA) && item.tipo_registro==='AGENDAMENTO') qtdAgd++;
 if (novos.includes(idV) && (item.tipo_registro==='VENDA_DIRETA_BALCAO'||item.tipo_registro==='LOJA_VIRTUAL')) qtdVnd++;
 });
 if (qtdAgd>0) { const m = qtdAgd+' novo(s) agendamento(s)!'; mostrarToast('📅 '+m,'aviso'); dispararNotificacaoBrowser('ALDINEICAR', m); }
 if (qtdVnd>0) { const m = qtdVnd+' nova(s) venda(s)!'; mostrarToast('💰 '+m,'sucesso'); dispararNotificacaoBrowser('ALDINEICAR', m); }
 salvarIdsVistos([...vistos, ...atuais]);
}
async function sincronizarEVerificarNotificacoes() {
 if (!usuarioAtualId || !notificacoesAtivas() || !navigator.onLine) return;
 try {
 const { data, error } = await supabaseClient.from('user_data').select('historico').eq('user_id', usuarioAtualId).single();
 if (error || !data) return;
 const lista = Array.isArray(data.historico) ? data.historico : [];
 if (lista.length !== (historico||[]).length) {
 historico = lista;
 const ag = document.getElementById('aba-agenda');
 if (ag && ag.style.display !== 'none') renderAgenda();
 const vd = document.getElementById('aba-vendas');
 if (vd && vd.style.display !== 'none' && typeof renderizarListaVendasExclusiva==='function') renderizarListaVendasExclusiva();
 }
 verificarNovasNotificacoes(lista);
 } catch(e){}
}
function iniciarMonitorNotificacoes() {
 if (!usuarioAtualId) return;
 if (notificacoesAtivas()) solicitarPermissaoNotificacoes();
 atualizarBotaoNotifUI();
 verificarNovasNotificacoes(historico||[]);
 if (monitorNotifInterval) clearInterval(monitorNotifInterval);
 monitorNotifInterval = setInterval(sincronizarEVerificarNotificacoes, 60000);
}

async function processarWebhookPix(payload) {

 if (!payload) return { ok: false, error: 'payload vazio' };
 const secretLocal = obterOuCriarWebhookSecret();
 if (payload.secret && payload.secret !== secretLocal && payload.secret !== (dadosOficina && dadosOficina.webhook_secret)) {
 return { ok: false, error: 'secret inválido' };
 }
 const uid = payload.user_id || usuarioAtualId;
 if (!uid) return { ok: false, error: 'user_id ausente' };

 try {
 const { data, error } = await supabaseClient.from('user_data').select('historico').eq('user_id', uid).single();
 if (error) throw error;
 let hist = Array.isArray(data.historico) ? data.historico : [];
 const txid = payload.txid || payload.pix_txid || payload.id_venda;
 let found = false;
 let produtoParaBaixa = null;
 let qtdBaixa = 0;
 hist = hist.map(item => {
 if (!item) return item;
 const match = (txid && (item.pix_txid === txid || item.id_venda === txid))
 || (payload.id_venda && item.id_venda === payload.id_venda);
 if (match) {
 found = true;
 if (String(item.status || '').includes('Aguardando') && item.produto_id) {
 produtoParaBaixa = item.produto_id;
 qtdBaixa = parseInt(item.quantidade) || 1;
 }
 item.status = 'Pago PIX';
 item.pagamento = 'PIX';
 item.webhook_confirmado_em = new Date().toISOString();
 }
 return item;
 });
 if (!found && payload.criar_venda) {
 hist.unshift({
 id_venda: payload.id_venda || ('VND-WH-' + Date.now()),
 data: new Date().toLocaleDateString('pt-BR'),
 status: 'Pago PIX',
 tipo_registro: 'VENDA_DIRETA_BALCAO',
 pagamento: 'PIX',
 pix_txid: txid || '',
 cliente: payload.cliente || { nome: 'Webhook', tel: '' },
 produto_nome: payload.produto_nome || 'Produto',
 quantidade: payload.quantidade || 1,
 total_pago: payload.valor || 0,
 lucro: payload.valor || 0,
 webhook_confirmado_em: new Date().toISOString()
 });
 found = true;
 }
 if (!found) return { ok: false, error: 'venda não encontrada' };

 await supabaseClient.from('user_data').update({ historico: hist, updated_at: new Date() }).eq('user_id', uid);
 if (produtoParaBaixa) {
 try {
 const { data: prod } = await supabaseClient.from('produtos_loja').select('estoque').eq('id', produtoParaBaixa).maybeSingle();
 if (prod) {
 const novo = Math.max(0, (parseInt(prod.estoque)||0) - (qtdBaixa||1));
 await supabaseClient.from('produtos_loja').update({ estoque: novo }).eq('id', produtoParaBaixa);
 }
 } catch (e) {}
 }
 if (uid === usuarioAtualId) {
 historico = hist;
 if (typeof renderizarListaVendasExclusiva === 'function') renderizarListaVendasExclusiva();
 if (typeof renderDashboard === 'function') {
 const dash = document.getElementById('aba-dashboard');
 if (dash && dash.style.display !== 'none') renderDashboard();
 }
 if (typeof mostrarToast === 'function') mostrarToast('Webhook: pagamento confirmado!', 'sucesso');
 dispararNotificacaoBrowser('ALDINEICAR', 'Pagamento PIX confirmado via webhook');
 }
 return { ok: true };
 } catch (e) {
 console.error('webhook', e);
 return { ok: false, error: e.message };
 }
}

window.processarWebhookPix = processarWebhookPix;

let realtimeChannel = null;
function iniciarRealtimeWebhook() {
 if (!usuarioAtualId || typeof supabaseClient.channel !== 'function') return;
 try {
 if (realtimeChannel) supabaseClient.removeChannel(realtimeChannel);
 realtimeChannel = supabaseClient
 .channel('user_data_webhook_' + usuarioAtualId)
 .on('postgres_changes', {
 event: 'UPDATE',
 schema: 'public',
 table: 'user_data',
 filter: 'user_id=eq.' + usuarioAtualId
 }, (payload) => {
 const novo = payload.new;
 if (novo && Array.isArray(novo.historico)) {
 const antes = (historico || []).length;
 historico = novo.historico;
 verificarNovasNotificacoes(historico);
 const ag = document.getElementById('aba-agenda');
 if (ag && ag.style.display !== 'none') renderAgenda();
 const vd = document.getElementById('aba-vendas');
 if (vd && vd.style.display !== 'none' && typeof renderizarListaVendasExclusiva === 'function') renderizarListaVendasExclusiva();
 if (historico.length > antes && typeof mostrarToast === 'function') {
 mostrarToast('Dados atualizados (webhook/realtime)', 'sucesso');
 }
 }
 })
 .subscribe();
 } catch (e) {
 console.warn('Realtime indisponível:', e);
 }
}

function pixCRC16(payload) {
 let crc = 0xFFFF;
 for (let i = 0; i < payload.length; i++) {
 crc ^= payload.charCodeAt(i) << 8;
 for (let j = 0; j < 8; j++) {
 crc = (crc & 0x8000) ? ((crc << 1) ^ 0x1021) : (crc << 1);
 crc &= 0xFFFF;
 }
 }
 return crc.toString(16).toUpperCase().padStart(4, '0');
}
function pixTLV(id, value) {
 const v = String(value);
 return id + String(v.length).padStart(2, '0') + v;
}
function gerarPayloadPix({ chave, nome, cidade, valor, txid }) {
 const chaveLimpa = String(chave).replace(/\s/g, '');
 const nomeLimpo = (nome || 'ALDINEICAR').substring(0, 25).normalize('NFD').replace(/[\u0300-\u036f]/g, '');
 const cidadeLimpa = (cidade || 'SATIRO DIAS').substring(0, 15).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase();
 const mai = pixTLV('00', 'BR.GOV.BCB.PIX') + pixTLV('01', chaveLimpa);
 let payload = pixTLV('00','01') + pixTLV('26', mai) + pixTLV('52','0000') + pixTLV('53','986')
 + pixTLV('54', Number(valor).toFixed(2)) + pixTLV('58','BR') + pixTLV('59', nomeLimpo)
 + pixTLV('60', cidadeLimpa) + pixTLV('62', pixTLV('05', (txid||'***').substring(0,25))) + '6304';
 payload += pixCRC16(payload);
 return payload;
}

function obterCategoriasLoja() {
 if (!dadosOficina || typeof dadosOficina !== 'object') return ['Geral'];
 if (!Array.isArray(dadosOficina.categorias_loja) || dadosOficina.categorias_loja.length === 0) {
 dadosOficina.categorias_loja = ['Geral'];
 }

 dadosOficina.categorias_loja = dadosOficina.categorias_loja
 .map(c => String(c || '').trim())
 .filter(Boolean);
 if (!dadosOficina.categorias_loja.length) dadosOficina.categorias_loja = ['Geral'];
 return dadosOficina.categorias_loja;
}

function preencherSelectCategoriasLoja(selecionada) {
 const sel = document.getElementById('prodCategoria');
 if (!sel) return;
 const cats = obterCategoriasLoja();
 sel.innerHTML = cats.map(c => '<option value="' + c.replace(/"/g, '&quot;') + '">' + c + '</option>').join('');
 if (selecionada && cats.includes(selecionada)) sel.value = selecionada;
 else sel.value = cats[0];
}

function renderBotoesCategoriasLoja() {
 const box = document.getElementById('botoesCategoriasLoja');
 if (!box) return;
 const cats = obterCategoriasLoja();
 let html = '<button type="button" id="btn-cat-loja-Todos" class="' + (categoriaLojaAtual === 'Todos' ? 'active btn-green' : '') + '" onclick="filtrarProdutosLoja(\'Todos\')">Todos</button>';
 cats.forEach(c => {
 const active = categoriaLojaAtual === c ? ' active' : '';
 const safe = c.replace(/'/g, "\\'");
 html += '<button type="button" id="btn-cat-loja-' + c.replace(/[^a-zA-Z0-9_-]/g, '_') + '" class="' + active + '" onclick="filtrarProdutosLoja(\'' + safe + '\')">' + c + '</button>';
 });
 box.innerHTML = html;
}

function filtrarProdutosLoja(cat) {
 categoriaLojaAtual = cat || 'Todos';
 renderBotoesCategoriasLoja();
 if (typeof renderizarProdutosLoja === 'function') renderizarProdutosLoja();
 else if (typeof carregarProdutosLoja === 'function') carregarProdutosLoja();
}

async function promptNovaCategoriaLoja(selecionarNoModal) {
 const nome = prompt('Nome da nova categoria da loja:');
 if (!nome || !nome.trim()) return;
 const cat = nome.trim();
 const cats = obterCategoriasLoja();
 if (cats.some(c => c.toLowerCase() === cat.toLowerCase())) {
 if (typeof mostrarToast === 'function') mostrarToast('Essa categoria já existe.', 'aviso');
 else alert('Essa categoria já existe.');
 preencherSelectCategoriasLoja(cat);
 return;
 }
 cats.push(cat);
 dadosOficina.categorias_loja = cats;
 if (typeof salvarNoBanco === 'function') await salvarNoBanco();
 renderBotoesCategoriasLoja();
 preencherSelectCategoriasLoja(cat);
 if (typeof mostrarToast === 'function') mostrarToast('Categoria "' + cat + '" criada.', 'sucesso');
}

function vitrineEstaAberta() {
 if (!dadosOficina) return true;
 return dadosOficina.vitrine_aberta !== false;
}

function atualizarUIVitrineAberta() {
 const aberta = vitrineEstaAberta();
 const badge = document.getElementById('badge-vitrine-status');
 const btn = document.getElementById('btn-toggle-vitrine');
 if (badge) {
 badge.textContent = aberta ? 'Aberta' : 'Fechada';
 badge.className = aberta ? 'badge-vitrine-on' : 'badge-vitrine-off';
 }
 if (btn) btn.textContent = aberta ? '⏸ Fechar vitrine' : '▶ Abrir vitrine';
}

async function alternarVitrineAberta() {
 if (!dadosOficina) dadosOficina = {};
 dadosOficina.vitrine_aberta = !vitrineEstaAberta();
 atualizarUIVitrineAberta();
 if (typeof salvarNoBanco === 'function') await salvarNoBanco();
 if (typeof mostrarToast === 'function') {
 mostrarToast(dadosOficina.vitrine_aberta ? 'Vitrine aberta ao público.' : 'Vitrine fechada.', 'sucesso');
 }
}

function prepararNovoProduto() {
 const idEl = document.getElementById('editandoId');
 if (idEl) idEl.value = '';
 const tit = document.getElementById('titulo-modal-produto');
 if (tit) tit.innerText = 'Novo Produto';
 ['prodImgUrl','prodNome','prodPreco','prodDesc','prodEstoque'].forEach(id => {
 const el = document.getElementById(id);
 if (el) el.value = '';
 });
 preencherSelectCategoriasLoja(categoriaLojaAtual !== 'Todos' ? categoriaLojaAtual : null);
 const modal = document.getElementById('modal-cadastro-produto');
 if (modal) modal.style.display = 'block';
}

async function prepararEdicaoProduto(id, nome, preco, descricao, estoque, imagem_url, categoria) {
 let prod = null;
 if (typeof produtosLoja !== 'undefined' && Array.isArray(produtosLoja)) {
 prod = produtosLoja.find(p => String(p.id) === String(id));
 }
 if (!prod && id) {
 try {
 const { data } = await supabaseClient.from('produtos_loja').select('*').eq('id', id).single();
 prod = data;
 } catch (e) {}
 }
 document.getElementById('titulo-modal-produto').innerText = 'Editar Produto';
 document.getElementById('editandoId').value = id || (prod && prod.id) || '';
 document.getElementById('prodImgUrl').value = (prod && prod.imagem_url) || (imagem_url && imagem_url !== 'null' ? imagem_url : '') || '';
 document.getElementById('prodNome').value = (prod && prod.nome) || nome || '';
 document.getElementById('prodPreco').value = (prod && prod.preco) != null ? prod.preco : (preco || '');
 document.getElementById('prodDesc').value = (prod && prod.descricao) || (descricao && descricao !== 'null' ? descricao : '') || '';
 document.getElementById('prodEstoque').value = (prod && prod.estoque) != null ? prod.estoque : (estoque || 0);
 preencherSelectCategoriasLoja((prod && prod.categoria) || categoria || 'Geral');
 document.getElementById('modal-cadastro-produto').style.display = 'block';
}

async function salvarProdutoLoja() {
 const id = document.getElementById('editandoId').value;
 const nome = (document.getElementById('prodNome').value || '').trim();
 const preco = parseFloat(document.getElementById('prodPreco').value);
 const descricao = document.getElementById('prodDesc').value || '';
 const estoque = parseInt(document.getElementById('prodEstoque').value, 10) || 0;
 const imagem_url = document.getElementById('prodImgUrl').value || '';
 const catEl = document.getElementById('prodCategoria');
 let categoria = catEl ? (catEl.value || '').trim() : 'Geral';
 if (!categoria) categoria = 'Geral';

 if (!nome || isNaN(preco)) {
 if (typeof mostrarToast === 'function') mostrarToast('Preencha nome e preço.', 'erro');
 else alert('Preencha nome e preço.');
 return;
 }

 const cats = obterCategoriasLoja();
 if (!cats.includes(categoria)) {
 cats.push(categoria);
 dadosOficina.categorias_loja = cats;
 if (typeof salvarNoBanco === 'function') await salvarNoBanco();
 }

 const user_id = usuarioAtualId;
 if (!user_id) {
 if (typeof mostrarToast === 'function') mostrarToast('Faça login para salvar.', 'erro');
 return;
 }

 const dadosProduto = { nome, preco, descricao, estoque, imagem_url, user_id, categoria };

 try {
 if (id) {
 const { error } = await supabaseClient.from('produtos_loja').update(dadosProduto).eq('id', id);
 if (error) throw error;
 if (typeof mostrarToast === 'function') mostrarToast('Produto atualizado!', 'sucesso');
 } else {
 const { error } = await supabaseClient.from('produtos_loja').insert([dadosProduto]);
 if (error) throw error;
 if (typeof mostrarToast === 'function') mostrarToast('Produto cadastrado!', 'sucesso');
 }
 fecharModalProduto();
 if (typeof carregarProdutosLoja === 'function') await carregarProdutosLoja();
 else if (typeof carregarProdutosDaLoja === 'function') await carregarProdutosDaLoja();
 renderBotoesCategoriasLoja();
 } catch (error) {
 console.error(error);
 if (typeof mostrarToast === 'function') mostrarToast('Erro: ' + (error.message || error), 'erro');
 else alert('Erro: ' + (error.message || error));
 }
}

function fecharModalProduto() {
 const m = document.getElementById('modal-cadastro-produto');
 if (m) m.style.display = 'none';
}

const _carregarProdutosLojaOriginal = typeof carregarProdutosLoja === 'function' ? carregarProdutosLoja : null;
async function carregarProdutosLoja() {
 const container = document.getElementById('vitrine-produtos');
 if (!container) return;
 container.innerHTML = '<p style="color:#64748b;padding:16px;text-align:center;">Carregando...</p>';
 const user_id = usuarioAtualId;
 if (!user_id) return;
 try {
 const { data, error } = await supabaseClient
 .from('produtos_loja')
 .select('*')
 .eq('user_id', user_id)
 .order('created_at', { ascending: false });
 if (error) throw error;
 produtosLoja = data || [];

 const cats = obterCategoriasLoja();
 produtosLoja.forEach(p => {
 if (p.categoria && !cats.includes(p.categoria)) cats.push(p.categoria);
 });
 dadosOficina.categorias_loja = cats;
 renderBotoesCategoriasLoja();
 renderizarProdutosLoja();
 } catch (err) {
 console.error(err);
 container.innerHTML = '<p style="color:#ef4444;padding:16px;">Erro ao carregar produtos.</p>';
 }
}

function renderizarProdutosLoja() {
 const vitrine = document.getElementById('vitrine-produtos');
 if (!vitrine) return;
 const filtrados = (produtosLoja || []).filter(p => {
 if (categoriaLojaAtual === 'Todos') return true;
 return (p.categoria || 'Geral') === categoriaLojaAtual;
 });
 if (!filtrados.length) {
 vitrine.innerHTML = '<p class="lista-vazia" style="grid-column:1/-1;">Nenhum produto nesta categoria.</p>';
 return;
 }
 vitrine.innerHTML = filtrados.map(prod => {
 const img = prod.imagem_url
 ? '<img src="' + prod.imagem_url + '" alt="" style="width:100%;height:110px;object-fit:cover;border-radius:8px;margin-bottom:8px;background:#f1f5f9;">'
 : '<div style="width:100%;height:80px;background:#f1f5f9;border-radius:8px;margin-bottom:8px;display:flex;align-items:center;justify-content:center;color:#94a3b8;font-size:11px;">Sem foto</div>';
 const cat = prod.categoria || 'Geral';
 return '<div class="card mat-card" style="min-height:auto;padding:10px;">'
 + '<div class="mat-line1"><span class="mat-cat">' + cat + '</span>'
 + '<div class="mat-card-menu">'
 + '<button type="button" class="mat-icon-btn" onclick="prepararEdicaoProduto(\'' + prod.id + '\')">✏️</button>'
 + '<button type="button" class="mat-icon-btn mat-icon-del" onclick="deletarProdutoLoja(\'' + prod.id + '\')">🗑️</button>'
 + '</div></div>'
 + img
 + '<h3 class="mat-nome">' + (prod.nome || '') + '</h3>'
 + '<div class="mat-line2"><span class="mat-preco">R$ ' + parseFloat(prod.preco || 0).toFixed(2) + '</span>'
 + '<span style="font-size:11px;color:#64748b;">Est. ' + (prod.estoque || 0) + '</span></div>'
 + '</div>';
 }).join('');
}

(function patchMostrarAbaLoja() {
 const orig = window.mostrarAba;
 if (typeof orig !== 'function') return;
 window.mostrarAba = function(nome) {
 orig(nome);
 if (nome === 'loja') {
 if (typeof atualizarCardLinkVitrine === 'function') atualizarCardLinkVitrine();
 if (typeof carregarProdutosLoja === 'function') carregarProdutosLoja();
 if (typeof renderBotoesCategoriasLoja === 'function') renderBotoesCategoriasLoja();
 }
 };
})();

let categoriaVitrinePublica = 'Todos';
let produtosVitrinePublicaCache = [];
let idOficinaVitrinePublica = null;

function renderBotoesCategoriasLoja() {
 const box = document.getElementById('botoesCategoriasLoja');
 if (!box) return;
 const cats = obterCategoriasLoja();
 let html = '<button type="button" class="' + (categoriaLojaAtual === 'Todos' ? 'active btn-green' : '') + '" onclick="filtrarProdutosLoja(\'Todos\')">Todos</button>';
 cats.forEach(c => {
 const active = categoriaLojaAtual === c ? ' active' : '';
 const safe = String(c).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
 html += '<span class="cat-loja-chip' + (categoriaLojaAtual === c ? ' is-active' : '') + '">'
 + '<button type="button" class="cat-loja-btn' + active + '" onclick="filtrarProdutosLoja(\'' + safe + '\')">' + c + '</button>'
 + '<button type="button" class="cat-loja-del" title="Remover categoria" onclick="removerCategoriaLoja(\'' + safe + '\')">×</button>'
 + '</span>';
 });
 box.innerHTML = html;
}

async function removerCategoriaLoja(cat) {
 if (!cat) return;
 const cats = obterCategoriasLoja();
 if (cats.length <= 1) {
 if (typeof mostrarToast === 'function') mostrarToast('Mantenha ao menos uma categoria.', 'aviso');
 return;
 }
 const emUso = (typeof produtosLoja !== 'undefined' && produtosLoja.some(p => (p.categoria || 'Geral') === cat));
 const msg = emUso
 ? 'A categoria "' + cat + '" tem produtos. Remover mesmo assim? (produtos ficam em "Geral")'
 : 'Remover a categoria "' + cat + '"?';
 if (!confirm(msg)) return;

 dadosOficina.categorias_loja = cats.filter(c => c !== cat);
 if (!dadosOficina.categorias_loja.length) dadosOficina.categorias_loja = ['Geral'];

 if (emUso && usuarioAtualId) {
 try {
 const { data } = await supabaseClient.from('produtos_loja').select('id, categoria').eq('user_id', usuarioAtualId);
 const ids = (data || []).filter(p => (p.categoria || '') === cat).map(p => p.id);
 for (const id of ids) {
 await supabaseClient.from('produtos_loja').update({ categoria: 'Geral' }).eq('id', id);
 }
 if (!dadosOficina.categorias_loja.includes('Geral')) {
 dadosOficina.categorias_loja.unshift('Geral');
 }
 } catch (e) { console.error(e); }
 }

 if (categoriaLojaAtual === cat) categoriaLojaAtual = 'Todos';
 if (typeof salvarNoBanco === 'function') await salvarNoBanco();
 renderBotoesCategoriasLoja();
 preencherSelectCategoriasLoja();
 if (typeof carregarProdutosLoja === 'function') await carregarProdutosLoja();
 if (typeof mostrarToast === 'function') mostrarToast('Categoria removida.', 'sucesso');
}

async function alternarVitrineAberta() {
 if (!dadosOficina) dadosOficina = {};
 const atual = dadosOficina.vitrine_aberta !== false;
 dadosOficina.vitrine_aberta = !atual;

 if (typeof salvarNoBanco === 'function') {
 await salvarNoBanco(true);
 }
 atualizarUIVitrineAberta();
 if (typeof mostrarToast === 'function') {
 mostrarToast(dadosOficina.vitrine_aberta ? 'Vitrine aberta ao público.' : 'Vitrine fechada ao público.', 'sucesso');
 }
}

function vitrineEstaAberta() {
 if (!dadosOficina) return true;
 return dadosOficina.vitrine_aberta !== false;
}

async function carregarProdutosVitrinePublica(idOficina) {
 const containerVitrine = document.getElementById('vitrine-publica-cliente');
 const filtrosBox = document.getElementById('filtros-vitrine-publica');
 if (!containerVitrine) return;
 idOficinaVitrinePublica = idOficina;
 containerVitrine.innerHTML = '<p style="color:#a1a1aa;grid-column:1/-1;text-align:center;padding:24px;">Carregando produtos...</p>';
 if (filtrosBox) filtrosBox.innerHTML = '';

 try {

 let oficina = null;
 try {
 const { data } = await supabaseClient.from('user_data').select('dados_oficina').eq('user_id', idOficina).single();
 oficina = data && data.dados_oficina ? data.dados_oficina : null;
 } catch (e) {}

 if (typeof aplicarTextosVitrinePublica === 'function') aplicarTextosVitrinePublica(oficina || {});

 if (oficina && oficina.vitrine_aberta === false) {
 containerVitrine.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:48px 20px;color:#a1a1aa;">'
 + '<div style="font-size:36px;margin-bottom:10px;">🔒</div>'
 + '<p style="font-size:16px;font-weight:700;color:#fff;margin:0 0 6px;">Vitrine temporariamente fechada</p>'
 + '<p style="font-size:13px;margin:0;">Volte mais tarde ou fale com a oficina.</p></div>';
 return;
 }

 const { data: produtos, error } = await supabaseClient
 .from('produtos_loja')
 .select('*')
 .eq('user_id', idOficina)
 .order('created_at', { ascending: false });
 if (error) throw error;

 produtosVitrinePublicaCache = produtos || [];

 let cats = [];
 if (oficina && Array.isArray(oficina.categorias_loja)) cats = oficina.categorias_loja.slice();
 produtosVitrinePublicaCache.forEach(p => {
 const c = (p.categoria || 'Geral').trim();
 if (c && !cats.includes(c)) cats.push(c);
 });
 if (!cats.length) cats = ['Geral'];

 window.__catsVitrinePublica = cats;
 renderFiltrosVitrinePublica(cats);
 renderVitrinePublicaFiltrada();
 bindFiltrosVitrinePublica();
 } catch (err) {
 console.error('Erro vitrine pública:', err);
 containerVitrine.innerHTML = '<p style="color:#e11d48;grid-column:1/-1;text-align:center;">Erro ao carregar produtos.</p>';
 }
}

function filtrarVitrinePublica(cat) {
 categoriaVitrinePublica = cat || 'Todos';
 const cats = (window.__catsVitrinePublica && window.__catsVitrinePublica.length)
 ? window.__catsVitrinePublica
 : (function() {
 const arr = [];
 (produtosVitrinePublicaCache || []).forEach(p => {
 const c = (p.categoria || 'Geral').trim();
 if (c && !arr.includes(c)) arr.push(c);
 });
 return arr.length ? arr : ['Geral'];
 })();
 renderFiltrosVitrinePublica(cats);
 renderVitrinePublicaFiltrada();
}

function bindFiltrosVitrinePublica() {
 const box = document.getElementById('filtros-vitrine-publica');
 if (!box || box.__boundFiltros) return;
 box.__boundFiltros = true;
 box.addEventListener('click', function(e) {
 const btn = e.target.closest('button[data-cat]');
 if (!btn) return;
 e.preventDefault();
 filtrarVitrinePublica(btn.getAttribute('data-cat'));
 });
}

function renderFiltrosVitrinePublica(cats) {
 const box = document.getElementById('filtros-vitrine-publica');
 if (!box) return;
 const all = ['Todos'].concat(cats || []);
 box.innerHTML = all.map(c => {
 const active = categoriaVitrinePublica === c;
 const safe = String(c).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
 return '<button type="button" class="vt-chip' + (active ? ' active' : '') + '" onclick="filtrarVitrinePublica(\'' + safe + '\')">' + c + '</button>';
 }).join('');
}

function renderVitrinePublicaFiltrada() {
 const containerVitrine = document.getElementById('vitrine-publica-cliente');
 if (!containerVitrine) return;
 const lista = (produtosVitrinePublicaCache || []).filter(p => {
 if (categoriaVitrinePublica === 'Todos') return true;
 return (p.categoria || 'Geral') === categoriaVitrinePublica;
 });
 const contagem = document.getElementById('vt-contagem-produtos');
 if (contagem) {
 contagem.textContent = lista.length ? (lista.length + (lista.length === 1 ? ' item' : ' itens')) : '';
 }
 if (!lista.length) {
 containerVitrine.innerHTML = '<div class="vt-empty"><div class="vt-empty-icon">🛒</div><p>Nenhum produto nesta categoria.</p></div>';
 return;
 }
 const imgPadrao = 'data:image/svg+xml,' + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="200" height="200"><rect fill="%2318181b" width="200" height="200"/><text x="50%" y="50%" fill="%2371717a" font-size="14" text-anchor="middle" dy=".3em">Sem foto</text></svg>');
 containerVitrine.innerHTML = lista.map(prod => {
 const urlImagem = prod.imagem_url || imgPadrao;
 const cat = prod.categoria || 'Geral';
 const nomeSafe = (prod.nome || '').replace(/\\/g, '\\\\').replace(/'/g, "\\'");
 const preco = parseFloat(prod.preco || 0).toFixed(2).replace('.', ',');
 const estoque = parseInt(prod.estoque, 10) || 0;
 const estoqueLbl = estoque > 0 ? (estoque + ' em estoque') : 'Consulte disponibilidade';
 return (
 '<article class="vt-card">'
 + '<div class="vt-card-img-wrap">'
 + '<span class="vt-card-cat">' + cat + '</span>'
 + '<img class="vt-card-img" src="' + urlImagem.replace(/"/g, '&quot;') + '" alt="' + (prod.nome || '').replace(/"/g, '&quot;') + '" loading="lazy" onerror="this.onerror=null;this.src=\'' + imgPadrao + '\';">'
 + '</div>'
 + '<div class="vt-card-body">'
 + '<h3 class="vt-card-title">' + (prod.nome || '') + '</h3>'
 + '<p class="vt-card-desc">' + (prod.descricao || 'Produto disponível na oficina.') + '</p>'
 + '<div class="vt-card-foot">'
 + '<div><div class="vt-card-price">R$ ' + preco + '</div>'
 + '<div class="vt-card-stock">' + estoqueLbl + '</div></div>'
 + '<button type="button" class="vt-card-buy" onclick="abrirModalCompra(\'' + prod.id + '\',\'' + nomeSafe + '\',\'' + prod.preco + '\',\'' + estoque + '\')">Comprar</button>'
 + '</div></div></article>'
 );
 }).join('');
}

function limparFotoProduto() {
 const hidden = document.getElementById('prodImgUrl');
 const file = document.getElementById('prodImgFile');
 const prev = document.getElementById('prodImgPreview');
 const antiga = hidden ? hidden.value : '';
 if (hidden) hidden.value = '';
 if (file) file.value = '';
 if (prev) {
 prev.style.backgroundImage = '';
 prev.classList.remove('tem-foto');
 prev.innerHTML = '📷 Toque para escolher da galeria';
 }
 if (antiga) {
 apagarFotoStorageSeExistir(antiga).catch(function(){});
 }
}

function mostrarPreviewProduto(dataUrl) {
 const prev = document.getElementById('prodImgPreview');
 const hidden = document.getElementById('prodImgUrl');
 if (hidden) hidden.value = dataUrl || '';
 if (!prev) return;
 if (dataUrl) {
 prev.textContent = '';
 prev.style.backgroundImage = 'url(' + dataUrl + ')';
 prev.classList.add('has-img');
 } else {
 limparFotoProduto();
 }
}

const STORAGE_BUCKET_FOTOS = 'fotos-oficina';

function dataUrlParaBlob(dataUrl) {
 try {
 var parts = String(dataUrl).split(',');
 var mime = (parts[0].match(/:(.*?);/) || [])[1] || 'image/jpeg';
 var bin = atob(parts[1] || '');
 var arr = new Uint8Array(bin.length);
 for (var i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
 return new Blob([arr], { type: mime });
 } catch (e) {
 return null;
 }
}

function extensaoMime(mime) {
 if (!mime) return 'jpg';
 if (mime.indexOf('png') >= 0) return 'png';
 if (mime.indexOf('webp') >= 0) return 'webp';
 return 'jpg';
}

async function uploadFotoOficina(dataUrl, pasta) {
 if (!dataUrl || typeof dataUrl !== 'string') return dataUrl || '';
 if (/^https?:\/\//i.test(dataUrl)) return dataUrl;
 if (!dataUrl.startsWith('data:')) return dataUrl;
 if (!usuarioAtualId || !supabaseClient || !supabaseClient.storage) return dataUrl;
 if (!navigator.onLine) return dataUrl;

 try {
 var blob = dataUrlParaBlob(dataUrl);
 if (!blob) return dataUrl;
 var ext = extensaoMime(blob.type);
 var pastaSegura = String(pasta || 'geral').replace(/[^a-z0-9_\-]/gi, '');
 var nome = usuarioAtualId + '/' + pastaSegura + '/' + Date.now() + '_' + Math.floor(Math.random() * 1e6) + '.' + ext;

 var up = await supabaseClient.storage
 .from(STORAGE_BUCKET_FOTOS)
 .upload(nome, blob, {
 contentType: blob.type || 'image/jpeg',
 upsert: true,
 cacheControl: '3600'
 });

 if (up.error) {
 console.warn('[Storage] upload falhou, usando Base64:', up.error.message || up.error);
 return dataUrl;
 }

 var pub = supabaseClient.storage.from(STORAGE_BUCKET_FOTOS).getPublicUrl(nome);
 var url = pub && pub.data && pub.data.publicUrl;
 return url || dataUrl;
 } catch (e) {
 console.warn('[Storage] erro:', e);
 return dataUrl;
 }
}

function isDataUrlImagem(v) {
 return typeof v === 'string' && v.indexOf('data:image') === 0;
}

function isUrlStorageOficina(v) {
 if (!v || typeof v !== 'string') return false;
 if (v.indexOf('http') !== 0) return false;
 return v.indexOf('/storage/v1/object/public/' + STORAGE_BUCKET_FOTOS + '/') >= 0
 || v.indexOf('/storage/v1/object/sign/' + STORAGE_BUCKET_FOTOS + '/') >= 0
 || (v.indexOf(STORAGE_BUCKET_FOTOS) >= 0 && v.indexOf('supabase') >= 0);
}

function extrairPathStorage(url) {
 try {
 if (!url || typeof url !== 'string') return null;
 var marker = '/object/public/' + STORAGE_BUCKET_FOTOS + '/';
 var i = url.indexOf(marker);
 if (i < 0) {
 marker = '/object/sign/' + STORAGE_BUCKET_FOTOS + '/';
 i = url.indexOf(marker);
 }
 if (i < 0) return null;
 var path = decodeURIComponent(url.slice(i + marker.length).split('?')[0]);
 return path || null;
 } catch (e) {
 return null;
 }
}

async function apagarFotoStorageSeExistir(url) {
 try {
 if (!isUrlStorageOficina(url)) return false;
 if (!supabaseClient || !supabaseClient.storage || !usuarioAtualId) return false;
 var path = extrairPathStorage(url);
 if (!path) return false;

 if (path.indexOf(usuarioAtualId + '/') !== 0) {
 console.warn('[Storage] recusou apagar path de outro usuário');
 return false;
 }
 var res = await supabaseClient.storage.from(STORAGE_BUCKET_FOTOS).remove([path]);
 if (res.error) {
 console.warn('[Storage] falha ao apagar:', res.error.message || res.error);
 return false;
 }
 console.log('[Storage] arquivo removido:', path);
 return true;
 } catch (e) {
 console.warn('[Storage] erro ao apagar:', e);
 return false;
 }
}

var __migracaoFotosRodando = false;
async function migrarFotosBase64ParaStorage() {
 if (__migracaoFotosRodando) return;
 if (!usuarioAtualId || !navigator.onLine) return;
 if (!supabaseClient || !supabaseClient.storage) return;
 __migracaoFotosRodando = true;
 var mudou = false;
 var migradas = 0;
 try {

 if (dadosOficina && isDataUrlImagem(dadosOficina.logoBase64)) {
 var logoUrl = await uploadFotoOficina(dadosOficina.logoBase64, 'logo');
 if (logoUrl && logoUrl !== dadosOficina.logoBase64 && !isDataUrlImagem(logoUrl)) {
 dadosOficina.logoBase64 = logoUrl;
 mudou = true;
 migradas++;
 if (typeof atualizarLogoHeader === 'function') atualizarLogoHeader();
 }
 }

 if (dadosOficina && Array.isArray(dadosOficina.servicos_vitrine)) {
 for (var s = 0; s < dadosOficina.servicos_vitrine.length; s++) {
 var serv = dadosOficina.servicos_vitrine[s];
 if (!serv) continue;
 var foto = serv.foto || serv.imagem || serv.imagem_url;
 if (isDataUrlImagem(foto)) {
 var u = await uploadFotoOficina(foto, 'servicos');
 if (u && !isDataUrlImagem(u)) {
 if (serv.foto !== undefined) serv.foto = u;
 if (serv.imagem !== undefined) serv.imagem = u;
 if (serv.imagem_url !== undefined) serv.imagem_url = u;
 if (serv.foto === undefined && serv.imagem === undefined) serv.foto = u;
 mudou = true;
 migradas++;
 }
 }
 }
 }

 if (Array.isArray(historico)) {
 var limite = Math.min(historico.length, 30);
 for (var h = 0; h < limite; h++) {
 var item = historico[h];
 if (!item || !Array.isArray(item.fotos) || !item.fotos.length) continue;
 for (var f = 0; f < item.fotos.length && f < 4; f++) {
 if (isDataUrlImagem(item.fotos[f])) {
 var uf = await uploadFotoOficina(item.fotos[f], 'orcamentos');
 if (uf && !isDataUrlImagem(uf)) {
 item.fotos[f] = uf;
 mudou = true;
 migradas++;
 }
 }
 }
 }
 }

 try {
 var pr = await supabaseClient
 .from('produtos_loja')
 .select('id, imagem_url')
 .eq('user_id', usuarioAtualId);
 if (pr.data && pr.data.length) {
 for (var p = 0; p < pr.data.length; p++) {
 var prod = pr.data[p];
 if (!prod || !isDataUrlImagem(prod.imagem_url)) continue;
 var up = await uploadFotoOficina(prod.imagem_url, 'produtos');
 if (up && !isDataUrlImagem(up)) {
 await supabaseClient.from('produtos_loja').update({ imagem_url: up }).eq('id', prod.id);
 migradas++;
 mudou = true;
 }
 }
 if (typeof carregarProdutosDaLoja === 'function') carregarProdutosDaLoja();
 else if (typeof carregarProdutosLoja === 'function') carregarProdutosLoja();
 }
 } catch (ep) {
 console.warn('[Storage] migração produtos:', ep);
 }

 if (mudou) {
 if (typeof salvarNoBanco === 'function') {
 try { await salvarNoBanco(true, true); } catch (es) {
 try { await salvarNoBanco(true); } catch (e2) {}
 }
 }
 if (typeof mostrarToast === 'function' && migradas > 0) {
 mostrarToast(migradas + ' foto(s) antiga(s) enviada(s) ao Storage.', 'sucesso');
 }
 }
 } catch (e) {
 console.warn('[Storage] migração:', e);
 } finally {
 __migracaoFotosRodando = false;
 }
}

function redimensionarImagemArquivo(file, maxLado, qualidade) {
 maxLado = maxLado || 900;
 qualidade = (qualidade == null ? 0.72 : qualidade);
 return new Promise(function(resolve, reject) {
 if (!file || !file.type || file.type.indexOf('image/') !== 0) {
 reject(new Error('Arquivo inválido'));
 return;
 }

 const reader = new FileReader();
 reader.onerror = function() { reject(new Error('Falha ao ler imagem')); };
 reader.onload = function() {
 const img = new Image();
 img.onload = function() {
 let w = img.width || 1;
 let h = img.height || 1;
 const precisaReduzir = (w > maxLado || h > maxLado || (file.size && file.size > 220000));
 if (!precisaReduzir && file.type === 'image/jpeg' && file.size && file.size < 180000) {
 resolve(reader.result);
 return;
 }
 if (w > maxLado || h > maxLado) {
 if (w > h) { h = Math.round(h * (maxLado / w)); w = maxLado; }
 else { w = Math.round(w * (maxLado / h)); h = maxLado; }
 }

 w = Math.max(1, Math.round(w));
 h = Math.max(1, Math.round(h));
 const canvas = document.createElement('canvas');
 canvas.width = w;
 canvas.height = h;
 const ctx = canvas.getContext('2d');
 if (ctx) {
 ctx.fillStyle = '#ffffff';
 ctx.fillRect(0, 0, w, h);
 ctx.drawImage(img, 0, 0, w, h);
 }
 let out = canvas.toDataURL('image/jpeg', qualidade);

 if (out.length > 900000) out = canvas.toDataURL('image/jpeg', 0.58);
 if (out.length > 900000) out = canvas.toDataURL('image/jpeg', 0.45);
 resolve(out);
 };
 img.onerror = function() { reject(new Error('Imagem inválida')); };
 img.src = reader.result;
 };
 reader.readAsDataURL(file);
 });
}

